@Test
public void TestAlterTableSetAvroProperties() {
    // Test set tblproperties with avro.schema.url and avro.schema.literal
    // TODO: Include customized schema files
    for (String propertyType : Lists.newArrayList("tblproperties", "serdeproperties")) {
        // Valid url with valid schema
        AnalyzesOk(String.format("alter table functional.alltypes set %s" + "('avro.schema.url'=" + "'hdfs:///test-warehouse/avro_schemas/functional/alltypes.json')", propertyType));
        // Invalid schema URL
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.url'='')", propertyType), "Invalid avro.schema.url: . Can not create a Path from an empty string");
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.url'='hdfs://invalid*host/schema.avsc')", propertyType), "Failed to read Avro schema at: hdfs://invalid*host/schema.avsc. " + "Incomplete HDFS URI, no host: hdfs://invalid*host/schema.avsc");
        AnalysisError(String.format("alter table functional.alltypes set %s" + "('avro.schema.url'='schema.avsc')", propertyType), "Invalid avro.schema.url: schema.avsc. Path does not exist.");
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.url'='foo://bar/schema.avsc')", propertyType), "Failed to read Avro schema at: foo://bar/schema.avsc. " + "No FileSystem for scheme: foo");
        // Valid schema literal
        AnalyzesOk(String.format("alter table functional.alltypes set %s" + "('avro.schema.literal'='{\"name\": \"my_record\", \"type\": \"record\", " + "\"fields\": [{\"name\": \"string1\", \"type\": \"string\"}] }')", propertyType));
        // Invalid schema
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='{\"name\": \"my_record\", \"type\": \"record\", " + "\"fields\": {\"name\": \"string1\", \"type\": \"string\"}]}')", propertyType), "Error parsing Avro schema for table 'functional.alltypes': " + "org.codehaus.jackson.JsonParseException: Unexpected close marker ']': " + "expected '}'");
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='')", propertyType), "Avro schema is null or empty: functional.alltypes");
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='{\"name\": \"my_record\"}')", propertyType), "Error parsing Avro schema for table 'functional.alltypes': " + "No type: {\"name\":\"my_record\"}");
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='{\"name\":\"my_record\", \"type\": \"record\"}')", propertyType), "Error parsing Avro schema for table 'functional.alltypes': " + "Record has no fields: {\"name\":\"my_record\",\"type\":\"record\"}");
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='" + "{\"type\":\"record\", \"fields\":[ {\"name\":\"fff\",\"type\":\"int\"} ] }')", propertyType), "Error parsing Avro schema for table 'functional.alltypes': " + "No name in schema: {\"type\":\"record\",\"fields\":[{\"name\":\"fff\"," + "\"type\":\"int\"}]}");
        // Unsupported types
        // Union
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='{\"name\": \"my_record\", \"type\": \"record\", " + "\"fields\": [{\"name\": \"string1\", \"type\": \"string\"}," + "{\"name\": \"union1\", \"type\": [\"float\", \"boolean\"]}]}')", propertyType), "Unsupported type 'union' of column 'union1'");
        // Check avro.schema.url and avro.schema.literal evaluation order,
        // skip checking url when literal is provided.
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='{\"name\": \"my_record\", \"type\": \"record\", " + "\"fields\": {\"name\": \"string1\", \"type\": \"string\"}]}', " + "'avro.schema.url'='')", propertyType), "Error parsing Avro schema for table 'functional.alltypes': " + "org.codehaus.jackson.JsonParseException: Unexpected close marker ']': " + "expected '}'");
        // Url is invalid but ignored because literal is provided.
        AnalyzesOk(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='{\"name\": \"my_record\", \"type\": \"record\", " + "\"fields\": [{\"name\": \"string1\", \"type\": \"string\"}] }', " + "'avro.schema.url'='')", propertyType));
        // Even though url is valid, literal has higher priority.
        AnalysisError(String.format("alter table functional.alltypes set %s " + "('avro.schema.literal'='', 'avro.schema.url'=" + "'hdfs:///test-warehouse/avro_schemas/functional/alltypes.json')", propertyType), "Avro schema is null or empty: functional.alltypes");
    }
}

