/**
 * Validate if location path analysis issues proper warnings when directory
 * permissions/existence checks fail.
 */
@Test
public void TestPermissionValidation() throws AnalysisException {
    String location = "/test-warehouse/.tmp_" + UUID.randomUUID().toString();
    Path parentPath = FileSystemUtil.createFullyQualifiedPath(new Path(location));
    FileSystem fs = null;
    try {
        fs = parentPath.getFileSystem(FileSystemUtil.getConfiguration());
        // Test location doesn't exist
        AnalyzesOk(String.format("create table new_table (col INT) location '%s/new_table'", location), String.format("Path '%s' cannot be reached: Path does not exist.", parentPath));
        // Test localtion path with trailing slash.
        AnalyzesOk(String.format("create table new_table (col INT) location " + "'%s/new_table/'", location), String.format("Path '%s' cannot be reached: Path does not exist.", parentPath));
        AnalyzesOk(String.format("create table new_table location '%s/new_table' " + "as select 1, 1", location), String.format("Path '%s' cannot be reached: Path does not exist.", parentPath));
        AnalyzesOk(String.format("create table new_table like functional.alltypes " + "location '%s/new_table'", location), String.format("Path '%s' cannot be reached: Path does not exist.", parentPath));
        AnalyzesOk(String.format("create database new_db location '%s/new_db'", location), String.format("Path '%s' cannot be reached: Path does not exist.", parentPath));
        fs.mkdirs(parentPath);
        // Create a test data file for load data test
        FSDataOutputStream out = fs.create(new Path(parentPath, "test_loaddata/testdata.txt"));
        out.close();
        fs.setPermission(parentPath, new FsPermission(FsAction.NONE, FsAction.NONE, FsAction.NONE));
        // Test location exists but Impala doesn't have sufficient permission
        AnalyzesOk(String.format("create data Source serverlog location " + "'%s/foo.jar' class 'foo.Bar' API_VERSION 'V1'", location), String.format("Impala does not have READ access to path '%s'", parentPath));
        AnalyzesOk(String.format("create external table new_table (col INT) location " + "'%s/new_table'", location), String.format("Impala does not have READ_WRITE access to path '%s'", parentPath));
        AnalyzesOk(String.format("alter table functional.insert_string_partitioned " + "add partition (s2='hello') location '%s/new_partition'", location), String.format("Impala does not have READ_WRITE access to path '%s'", parentPath));
        AnalyzesOk(String.format("alter table functional.stringpartitionkey " + "partition(string_col = 'partition1') set location '%s/new_part_loc'", location), String.format("Impala does not have READ_WRITE access to path '%s'", parentPath));
        // Test location exists and Impala does have sufficient permission
        fs.setPermission(parentPath, new FsPermission(FsAction.READ_WRITE, FsAction.NONE, FsAction.NONE));
        AnalyzesOk(String.format("create external table new_table (col INT) location " + "'%s/new_table'", location));
    } catch (IOException e) {
        throw new AnalysisException(e.getMessage(), e);
    } finally {
        // Clean up
        try {
            if (fs != null && fs.exists(parentPath)) {
                fs.delete(parentPath, true);
            }
        } catch (IOException e) {
            // Ignore
        }
    }
}

@Test
public void TestNumericLiteralMinMaxValues() {
    testNumericLiteral(Byte.toString(Byte.MIN_VALUE), Type.TINYINT);
    testNumericLiteral(Byte.toString(Byte.MAX_VALUE), Type.TINYINT);
    testNumericLiteral("- " + Byte.toString(Byte.MIN_VALUE), Type.SMALLINT);
    testNumericLiteral("- " + Byte.toString(Byte.MAX_VALUE), Type.TINYINT);
    testNumericLiteral(Short.toString(Short.MIN_VALUE), Type.SMALLINT);
    testNumericLiteral(Short.toString(Short.MAX_VALUE), Type.SMALLINT);
    testNumericLiteral("- " + Short.toString(Short.MIN_VALUE), Type.INT);
    testNumericLiteral("- " + Short.toString(Short.MAX_VALUE), Type.SMALLINT);
    testNumericLiteral(Integer.toString(Integer.MIN_VALUE), Type.INT);
    testNumericLiteral(Integer.toString(Integer.MAX_VALUE), Type.INT);
    testNumericLiteral("- " + Integer.toString(Integer.MIN_VALUE), Type.BIGINT);
    testNumericLiteral("- " + Integer.toString(Integer.MAX_VALUE), Type.INT);
    testNumericLiteral(Long.toString(Long.MIN_VALUE), Type.BIGINT);
    testNumericLiteral(Long.toString(Long.MAX_VALUE), Type.BIGINT);
    testNumericLiteral(Long.toString(Long.MIN_VALUE), Type.BIGINT);
    testNumericLiteral("- " + Long.toString(Long.MAX_VALUE), Type.BIGINT);
    // Result type is a decimal because Long can't hold the value.
    testNumericLiteral(Long.toString(Long.MIN_VALUE) + "1", ScalarType.createDecimalType(20, 0));
    testNumericLiteral(Long.toString(Long.MIN_VALUE) + "1", ScalarType.createDecimalType(20, 0));
    // Test min int64-1.
    BigInteger minMinusOne = BigInteger.valueOf(Long.MIN_VALUE);
    minMinusOne = minMinusOne.subtract(BigInteger.ONE);
    testNumericLiteral(minMinusOne.toString(), ScalarType.createDecimalType(19, 0));
    // Test max int64+1.
    BigInteger maxPlusOne = BigInteger.valueOf(Long.MAX_VALUE);
    maxPlusOne = maxPlusOne.add(BigInteger.ONE);
    testNumericLiteral(maxPlusOne.toString(), ScalarType.createDecimalType(19, 0));
    // Test floating-point types.
    testNumericLiteral(Float.toString(Float.MIN_VALUE), Type.DOUBLE);
    testNumericLiteral(Float.toString(Float.MAX_VALUE), Type.DOUBLE);
    testNumericLiteral("-" + Float.toString(Float.MIN_VALUE), Type.DOUBLE);
    testNumericLiteral("-" + Float.toString(Float.MAX_VALUE), Type.DOUBLE);
    testNumericLiteral(Double.toString(Double.MIN_VALUE), Type.DOUBLE);
    testNumericLiteral(Double.toString(Double.MAX_VALUE), Type.DOUBLE);
    testNumericLiteral("-" + Double.toString(Double.MIN_VALUE), Type.DOUBLE);
    testNumericLiteral("-" + Double.toString(Double.MAX_VALUE), Type.DOUBLE);
    AnalysisError(String.format("select %s1", Double.toString(Double.MAX_VALUE)), "Numeric literal '1.7976931348623157E+3081' exceeds maximum range of doubles.");
    AnalysisError(String.format("select %s1", Double.toString(Double.MIN_VALUE)), "Numeric literal '4.9E-3241' underflows minimum resolution of doubles.");
    testNumericLiteral("0.99999999999999999999999999999999999999", ScalarType.createDecimalType(38, 38));
    testNumericLiteral("99999999999999999999999999999999999999.", ScalarType.createDecimalType(38, 0));
    testNumericLiteral("-0.99999999999999999999999999999999999999", ScalarType.createDecimalType(38, 38));
    testNumericLiteral("-99999999999999999999999999999999999999.", ScalarType.createDecimalType(38, 0));
    testNumericLiteral("999999999999999999999.99999999999999999", ScalarType.createDecimalType(38, 17));
    testNumericLiteral("-999999999999999999.99999999999999999999", ScalarType.createDecimalType(38, 20));
}

