/**
 * Test of all arithmetic type casts.
 */
@Test
public void TestArithmeticTypeCasts() throws AnalysisException {
    // Test all non-decimal numeric types and the null type.
    // Decimal has custom type promotion rules which are tested elsewhere.
    Type[] numericTypes = new Type[] { Type.TINYINT, Type.SMALLINT, Type.INT, Type.BIGINT, Type.FLOAT, Type.DOUBLE, Type.NULL };
    for (Type type1 : numericTypes) {
        for (Type type2 : numericTypes) {
            Type t = Type.getAssignmentCompatibleType(type1, type2, false);
            assertTrue(t.isScalarType());
            ScalarType compatibleType = (ScalarType) t;
            Type promotedType = compatibleType.getNextResolutionType();
            boolean inputsNull = false;
            if (type1.isNull() && type2.isNull()) {
                inputsNull = true;
                promotedType = Type.DOUBLE;
                compatibleType = Type.INT;
            }
            // +, -, *, %
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.ADD, null, promotedType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.ADD, null, promotedType);
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.SUBTRACT, null, promotedType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.SUBTRACT, null, promotedType);
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.MULTIPLY, null, promotedType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.MULTIPLY, null, promotedType);
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.MOD, null, inputsNull ? Type.DOUBLE : compatibleType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.MOD, null, inputsNull ? Type.DOUBLE : compatibleType);
            // /
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.DIVIDE, null, Type.DOUBLE);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.DIVIDE, null, Type.DOUBLE);
            // div, &, |, ^ only for fixed-point types
            if ((!type1.isFixedPointType() && !type1.isNull()) || (!type2.isFixedPointType() && !type2.isNull())) {
                continue;
            }
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.INT_DIVIDE, null, compatibleType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.INT_DIVIDE, null, compatibleType);
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.BITAND, null, compatibleType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.BITAND, null, compatibleType);
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.BITOR, null, compatibleType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.BITOR, null, compatibleType);
            typeCastTest(type1, type2, false, ArithmeticExpr.Operator.BITXOR, null, compatibleType);
            typeCastTest(type1, type2, true, ArithmeticExpr.Operator.BITXOR, null, compatibleType);
        }
    }
    List<Type> fixedPointTypes = new ArrayList<Type>(Type.getIntegerTypes());
    fixedPointTypes.add(Type.NULL);
    for (Type type : fixedPointTypes) {
        typeCastTest(null, type, false, ArithmeticExpr.Operator.BITNOT, null, type.isNull() ? Type.INT : type);
    }
}

/**
 * Test of all type casts in comparisons following mysql's casting policy.
 */
@Test
public void TestComparisonTypeCasts() throws AnalysisException {
    // Test all non-decimal numeric types and the null type.
    // Decimal has custom type promotion rules which are tested elsewhere.
    Type[] types = new Type[] { Type.TINYINT, Type.SMALLINT, Type.INT, Type.BIGINT, Type.FLOAT, Type.DOUBLE, Type.NULL };
    // test on all comparison ops
    for (BinaryPredicate.Operator cmpOp : BinaryPredicate.Operator.values()) {
        for (Type type1 : types) {
            for (Type type2 : types) {
                // Prefer strict matching.
                Type compatibleType = Type.getAssignmentCompatibleType(type1, type2, true);
                if (compatibleType.isInvalid()) {
                    compatibleType = Type.getAssignmentCompatibleType(type1, type2, false);
                }
                typeCastTest(type1, type2, false, null, cmpOp, compatibleType);
                typeCastTest(type1, type2, true, null, cmpOp, compatibleType);
            }
        }
    }
}

@Test
public void TestNumericLiteralTypeResolution() throws AnalysisException {
    checkReturnType("select 1", Type.TINYINT);
    checkReturnType("select 1.1", ScalarType.createDecimalType(2, 1));
    checkReturnType("select 01.1", ScalarType.createDecimalType(2, 1));
    checkReturnType("select 1 + 1.1", Type.DOUBLE);
    checkReturnType("select 0.23 + 1.1", ScalarType.createDecimalType(4, 2));
    checkReturnType("select float_col + float_col from functional.alltypestiny", Type.DOUBLE);
    checkReturnType("select int_col + int_col from functional.alltypestiny", Type.BIGINT);
    // floating point + numeric literal = floating point
    checkReturnType("select float_col + 1.1 from functional.alltypestiny", Type.DOUBLE);
    // decimal + numeric literal = decimal
    checkReturnType("select d1 + 1.1 from functional.decimal_tbl", ScalarType.createDecimalType(11, 1));
    // int + numeric literal = floating point
    checkReturnType("select int_col + 1.1 from functional.alltypestiny", Type.DOUBLE);
    // Explicitly casting the literal to a decimal will override the behavior
    checkReturnType("select int_col + cast(1.1 as decimal(2,1)) from " + " functional.alltypestiny", ScalarType.createDecimalType(12, 1));
    checkReturnType("select float_col + cast(1.1 as decimal(2,1)) from " + " functional.alltypestiny", ScalarType.createDecimalType(38, 9));
    checkReturnType("select float_col + cast(1.1*1.2+1.3 as decimal(2,1)) from " + " functional.alltypestiny", ScalarType.createDecimalType(38, 9));
    // The location and complexity of the expr should not matter.
    checkReturnType("select 1.0 + float_col + 1.1 from functional.alltypestiny", Type.DOUBLE);
    checkReturnType("select 1.0 + 2.0 + float_col from functional.alltypestiny", Type.DOUBLE);
    checkReturnType("select 1.0 + 2.0 + pi() * float_col from functional.alltypestiny", Type.DOUBLE);
    checkReturnType("select 1.0 + d1 + 1.1 from functional.decimal_tbl", ScalarType.createDecimalType(12, 1));
    checkReturnType("select 1.0 + 2.0 + d1 from functional.decimal_tbl", ScalarType.createDecimalType(11, 1));
    checkReturnType("select 1.0 + 2.0 + pi()*d1 from functional.decimal_tbl", ScalarType.createDecimalType(38, 17));
    // Test with multiple cols
    checkReturnType("select double_col + 1.23 + float_col + 1.0 " + " from functional.alltypestiny", Type.DOUBLE);
    checkReturnType("select double_col + 1.23 + float_col + 1.0 + int_col " + " + bigint_col from functional.alltypestiny", Type.DOUBLE);
    checkReturnType("select d1 + 1.23 + d2 + 1.0 " + " from functional.decimal_tbl", ScalarType.createDecimalType(14, 2));
    // Test with slot of both decimal and non-decimal
    checkReturnType("select t1.int_col + t2.c1 from functional.alltypestiny t1 " + " cross join functional.decimal_tiny t2", ScalarType.createDecimalType(15, 4));
    checkReturnType("select 1.1 + t1.int_col + t2.c1 from functional.alltypestiny t1 " + " cross join functional.decimal_tiny t2", ScalarType.createDecimalType(38, 17));
}

