/**
 * We have three variants of timestamp arithmetic exprs, as in MySQL:
 * http://dev.mysql.com/doc/refman/5.5/en/date-and-time-functions.html
 * (section #function_date-add)
 * 1. Non-function-call like version, e.g., 'a + interval b timeunit'
 * 2. Beginning with an interval (only for '+'), e.g., 'interval b timeunit + a'
 * 3. Function-call like version, e.g., date_add(a, interval b timeunit)
 */
@Test
public void TestTimestampArithmeticExpressions() {
    String[] valueTypeCols = new String[] { "tinyint_col", "smallint_col", "int_col", "bigint_col", "NULL" };
    // Tests all time units.
    for (TimeUnit timeUnit : TimeUnit.values()) {
        // Tests on all valid time value types (fixed points).
        for (String col : valueTypeCols) {
            // Non-function call like version.
            AnalyzesOk("select timestamp_col + interval " + col + " " + timeUnit.toString() + " from functional.alltypes");
            AnalyzesOk("select timestamp_col - interval " + col + " " + timeUnit.toString() + " from functional.alltypes");
            AnalyzesOk("select NULL - interval " + col + " " + timeUnit.toString() + " from functional.alltypes");
            // Reversed interval and timestamp using addition.
            AnalyzesOk("select interval " + col + " " + timeUnit.toString() + " + timestamp_col from functional.alltypes");
            // Function-call like version.
            AnalyzesOk("select date_add(timestamp_col, interval " + col + " " + timeUnit.toString() + ") from functional.alltypes");
            AnalyzesOk("select date_sub(timestamp_col, interval " + col + " " + timeUnit.toString() + ") from functional.alltypes");
            AnalyzesOk("select date_add(NULL, interval " + col + " " + timeUnit.toString() + ") from functional.alltypes");
            AnalyzesOk("select date_sub(NULL, interval " + col + " " + timeUnit.toString() + ") from functional.alltypes");
        }
    }
    // First operand does not return a timestamp. Non-function-call like version.
    AnalysisError("select float_col + interval 10 years from functional.alltypes", "Operand 'float_col' of timestamp arithmetic expression " + "'float_col + INTERVAL 10 years' returns type 'FLOAT'. " + "Expected type 'TIMESTAMP'.");
    AnalysisError("select string_col + interval 10 years from functional.alltypes", "Operand 'string_col' of timestamp arithmetic expression " + "'string_col + INTERVAL 10 years' returns type 'STRING'. " + "Expected type 'TIMESTAMP'.");
    AnalysisError("select int_struct_col + interval 10 years from functional.allcomplextypes", "Operand 'int_struct_col' of timestamp arithmetic expression " + "'int_struct_col + INTERVAL 10 years' returns type 'STRUCT<f1:INT,f2:INT>'. " + "Expected type 'TIMESTAMP'.");
    // Reversed interval and timestamp using addition.
    AnalysisError("select interval 10 years + float_col from functional.alltypes", "Operand 'float_col' of timestamp arithmetic expression " + "'INTERVAL 10 years + float_col' returns type 'FLOAT'. " + "Expected type 'TIMESTAMP'");
    AnalysisError("select interval 10 years + string_col from functional.alltypes", "Operand 'string_col' of timestamp arithmetic expression " + "'INTERVAL 10 years + string_col' returns type 'STRING'. " + "Expected type 'TIMESTAMP'");
    AnalysisError("select interval 10 years + int_array_col from functional.allcomplextypes", "Operand 'int_array_col' of timestamp arithmetic expression " + "'INTERVAL 10 years + int_array_col' returns type 'ARRAY<INT>'. " + "Expected type 'TIMESTAMP'.");
    // First operand does not return a timestamp. Function-call like version.
    AnalysisError("select date_add(float_col, interval 10 years) " + "from functional.alltypes", "Operand 'float_col' of timestamp arithmetic expression " + "'DATE_ADD(float_col, INTERVAL 10 years)' returns type 'FLOAT'. " + "Expected type 'TIMESTAMP'.");
    AnalysisError("select date_add(string_col, interval 10 years) " + "from functional.alltypes", "Operand 'string_col' of timestamp arithmetic expression " + "'DATE_ADD(string_col, INTERVAL 10 years)' returns type 'STRING'. " + "Expected type 'TIMESTAMP'.");
    AnalysisError("select date_add(int_map_col, interval 10 years) " + "from functional.allcomplextypes", "Operand 'int_map_col' of timestamp arithmetic expression " + "'DATE_ADD(int_map_col, INTERVAL 10 years)' returns type 'MAP<STRING,INT>'. " + "Expected type 'TIMESTAMP'.");
    // Second operand is not compatible with a fixed-point type.
    // Non-function-call like version.
    AnalysisError("select timestamp_col + interval 5.2 years from functional.alltypes", "Operand '5.2' of timestamp arithmetic expression " + "'timestamp_col + INTERVAL 5.2 years' returns type 'DECIMAL(2,1)'. " + "Expected an integer type.");
    AnalysisError("select cast(0 as timestamp) + interval int_array_col years " + "from functional.allcomplextypes", "Operand 'int_array_col' of timestamp arithmetic expression " + "'CAST(0 AS TIMESTAMP) + INTERVAL int_array_col years' " + "returns type 'ARRAY<INT>'. Expected an integer type.");
    // No implicit cast from STRING to integer types.
    AnalysisError("select timestamp_col + interval '10' years from functional.alltypes", "Operand ''10'' of timestamp arithmetic expression 'timestamp_col + " + "INTERVAL '10' years' returns type 'STRING'. " + "Expected an integer type.");
    AnalysisError("select date_add(timestamp_col, interval '10' years) " + "from functional.alltypes", "Operand ''10'' of timestamp arithmetic " + "expression 'DATE_ADD(timestamp_col, INTERVAL '10' years)' returns " + "type 'STRING'. Expected an integer type.");
    // Cast from STRING to INT.
    AnalyzesOk("select timestamp_col + interval cast('10' as int) years " + "from functional.alltypes");
    // Reversed interval and timestamp using addition.
    AnalysisError("select interval 5.2 years + timestamp_col from functional.alltypes", "Operand '5.2' of timestamp arithmetic expression " + "'INTERVAL 5.2 years + timestamp_col' returns type 'DECIMAL(2,1)'. " + "Expected an integer type.");
    // Cast from STRING to INT.
    AnalyzesOk("select interval cast('10' as int) years + timestamp_col " + "from functional.alltypes");
    // Second operand is not compatible with type INT. Function-call like version.
    AnalysisError("select date_add(timestamp_col, interval 5.2 years) " + "from functional.alltypes", "Operand '5.2' of timestamp arithmetic expression " + "'DATE_ADD(timestamp_col, INTERVAL 5.2 years)' returns type 'DECIMAL(2,1)'. " + "Expected an integer type.");
    // Cast from STRING to INT.
    AnalyzesOk("select date_add(timestamp_col, interval cast('10' as int) years) " + " from functional.alltypes");
    // Invalid time unit. Non-function-call like version.
    AnalysisError("select timestamp_col + interval 10 error from functional.alltypes", "Invalid time unit 'error' in timestamp arithmetic expression " + "'timestamp_col + INTERVAL 10 error'.");
    AnalysisError("select timestamp_col - interval 10 error from functional.alltypes", "Invalid time unit 'error' in timestamp arithmetic expression " + "'timestamp_col - INTERVAL 10 error'.");
    // Reversed interval and timestamp using addition.
    AnalysisError("select interval 10 error + timestamp_col from functional.alltypes", "Invalid time unit 'error' in timestamp arithmetic expression " + "'INTERVAL 10 error + timestamp_col'.");
    // Invalid time unit. Function-call like version.
    AnalysisError("select date_add(timestamp_col, interval 10 error) " + "from functional.alltypes", "Invalid time unit 'error' in timestamp arithmetic expression " + "'DATE_ADD(timestamp_col, INTERVAL 10 error)'.");
    AnalysisError("select date_sub(timestamp_col, interval 10 error) " + "from functional.alltypes", "Invalid time unit 'error' in timestamp arithmetic expression " + "'DATE_SUB(timestamp_col, INTERVAL 10 error)'.");
}

@Test
public void TestFunctionCallExpr() throws AnalysisException {
    AnalyzesOk("select pi()");
    AnalyzesOk("select _impala_builtins.pi()");
    AnalyzesOk("select _impala_builtins.decode(1, 2, 3)");
    AnalyzesOk("select _impala_builtins.DECODE(1, 2, 3)");
    AnalyzesOk("select sin(pi())");
    AnalyzesOk("select sin(cos(pi()))");
    AnalyzesOk("select sin(cos(tan(e())))");
    AnalysisError("select pi(*)", "Cannot pass '*' to scalar function.");
    AnalysisError("select sin(DISTINCT 1)", "Cannot pass 'DISTINCT' to scalar function.");
    AnalysisError("select * from functional.alltypes where pi(*) = 5", "Cannot pass '*' to scalar function.");
    // Invalid function name.
    AnalysisError("select a.b.sin()", "Invalid function name: 'a.b.sin'. Expected [dbname].funcname");
    // Call function that only accepts decimal
    AnalyzesOk("select precision(1)");
    AnalyzesOk("select precision(cast('1.1' as decimal))");
    AnalyzesOk("select scale(1.1)");
    AnalysisError("select scale('1.1')", "No matching function with signature: scale(STRING).");
    AnalyzesOk("select round(cast('1.1' as decimal), cast(1 as int))");
    // 1 is a tinyint, so the function is not a perfect match
    AnalyzesOk("select round(cast('1.1' as decimal), 1)");
    // No matching signature for complex type.
    AnalysisError("select lower(int_struct_col) from functional.allcomplextypes", "No matching function with signature: lower(STRUCT<f1:INT,f2:INT>).");
    // Special cases for FROM in function call
    AnalyzesOk("select extract(year from now())");
    AnalysisError("select extract(foo from now())", "Time unit 'foo' in expression 'EXTRACT(foo FROM now())' is invalid. Expected " + "one of YEAR, MONTH, DAY, HOUR, MINUTE, SECOND, MILLISECOND, EPOCH.");
    AnalysisError("select extract(year from 0)", "Expression '0' in 'EXTRACT(year FROM 0)' has a return type of TINYINT but a " + "TIMESTAMP is required.");
    AnalysisError("select functional.extract(year from now())", "Function functional.extract conflicts with the EXTRACT builtin");
    AnalysisError("select date_part(year from now())", "Function DATE_PART does not accept the keyword FROM");
}

@Test
