@Test
public // Test matching function signatures.
void TestFunctionMatching() {
    Function[] fns = new Function[14];
    // test()
    fns[0] = createFunction(false);
    // test(int)
    fns[1] = createFunction(false, Type.INT);
    // test(int...)
    fns[2] = createFunction(true, Type.INT);
    // test(tinyint)
    fns[3] = createFunction(false, Type.TINYINT);
    // test(tinyint...)
    fns[4] = createFunction(true, Type.TINYINT);
    // test(double)
    fns[5] = createFunction(false, Type.DOUBLE);
    // test(double...)
    fns[6] = createFunction(true, Type.DOUBLE);
    // test(double, double)
    fns[7] = createFunction(false, Type.DOUBLE, Type.DOUBLE);
    // test(double, double...)
    fns[8] = createFunction(true, Type.DOUBLE, Type.DOUBLE);
    // test(smallint, tinyint)
    fns[9] = createFunction(false, Type.SMALLINT, Type.TINYINT);
    // test(int, double, double, double)
    fns[10] = createFunction(false, Type.INT, Type.DOUBLE, Type.DOUBLE, Type.DOUBLE);
    // test(int, string, int...)
    fns[11] = createFunction(true, Type.INT, Type.STRING, Type.INT);
    // test(tinying, string, tinyint, int, tinyint)
    fns[12] = createFunction(false, Type.TINYINT, Type.STRING, Type.TINYINT, Type.INT, Type.TINYINT);
    // test(tinying, string, bigint, int, tinyint)
    fns[13] = createFunction(false, Type.TINYINT, Type.STRING, Type.BIGINT, Type.INT, Type.TINYINT);
    Assert.assertFalse(fns[1].compare(fns[0], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(fns[1].compare(fns[2], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(fns[1].compare(fns[3], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(fns[1].compare(fns[4], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertFalse(fns[1].compare(fns[5], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertFalse(fns[1].compare(fns[6], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertFalse(fns[1].compare(fns[7], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertFalse(fns[1].compare(fns[8], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(fns[1].compare(fns[2], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertTrue(fns[3].compare(fns[4], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertTrue(fns[5].compare(fns[6], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertFalse(fns[5].compare(fns[7], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertFalse(fns[5].compare(fns[8], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertTrue(fns[6].compare(fns[7], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertTrue(fns[6].compare(fns[8], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertTrue(fns[7].compare(fns[8], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertFalse(fns[1].compare(fns[3], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertFalse(fns[1].compare(fns[4], Function.CompareMode.IS_INDISTINGUISHABLE));
    Assert.assertFalse(fns[9].compare(fns[4], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(fns[2].compare(fns[9], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(fns[8].compare(fns[10], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertFalse(fns[10].compare(fns[8], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertTrue(fns[11].compare(fns[12], Function.CompareMode.IS_SUPERTYPE_OF));
    Assert.assertFalse(fns[11].compare(fns[13], Function.CompareMode.IS_SUPERTYPE_OF));
    for (int i = 0; i < fns.length; ++i) {
        for (int j = 0; j < fns.length; ++j) {
            if (i == j) {
                Assert.assertTrue(fns[i].compare(fns[i], Function.CompareMode.IS_IDENTICAL));
                Assert.assertTrue(fns[i].compare(fns[i], Function.CompareMode.IS_INDISTINGUISHABLE));
                Assert.assertTrue(fns[i].compare(fns[i], Function.CompareMode.IS_SUPERTYPE_OF));
            } else {
                Assert.assertFalse(fns[i].compare(fns[j], Function.CompareMode.IS_IDENTICAL));
                if (fns[i].compare(fns[j], Function.CompareMode.IS_INDISTINGUISHABLE)) {
                    // If it's a indistinguishable, at least one of them must be a super type
                    // of the other
                    Assert.assertTrue(fns[i].compare(fns[j], Function.CompareMode.IS_SUPERTYPE_OF) || fns[j].compare(fns[i], Function.CompareMode.IS_SUPERTYPE_OF));
                } else if (fns[i].compare(fns[j], Function.CompareMode.IS_INDISTINGUISHABLE)) {
                    // This is reflexive
                    Assert.assertTrue(fns[j].compare(fns[i], Function.CompareMode.IS_INDISTINGUISHABLE));
                }
            }
        }
    }
}

@Test
public void TestCollectionTableRefs() throws AnalysisException {
    // Test ARRAY type referenced as a table.
    testAllTableAliases(new String[] { "allcomplextypes.int_array_col" }, new String[] { Path.ARRAY_POS_FIELD_NAME, Path.ARRAY_ITEM_FIELD_NAME, "*" });
    testAllTableAliases(new String[] { "allcomplextypes.struct_array_col" }, new String[] { "f1", "f2", "*" });
    // Test MAP type referenced as a table.
    testAllTableAliases(new String[] { "allcomplextypes.int_map_col" }, new String[] { Path.MAP_KEY_FIELD_NAME, Path.MAP_VALUE_FIELD_NAME, "*" });
    testAllTableAliases(new String[] { "allcomplextypes.struct_map_col" }, new String[] { Path.MAP_KEY_FIELD_NAME, "f1", "f2", "*" });
    // Test complex table ref path with structs and multiple collections.
    testAllTableAliases(new String[] { "allcomplextypes.complex_nested_struct_col.f2.f12" }, new String[] { Path.MAP_KEY_FIELD_NAME, "f21", "*" });
    // Test resolution of collection table refs.
    testCollectionTableRefs("int_array_col", Path.ARRAY_POS_FIELD_NAME);
    testCollectionTableRefs("int_array_col", Path.ARRAY_ITEM_FIELD_NAME);
    testCollectionTableRefs("int_map_col", Path.MAP_KEY_FIELD_NAME);
    testCollectionTableRefs("complex_nested_struct_col.f2.f12", "f21");
    // Path resolution error is reported before duplicate alias.
    AnalysisError("select 1 from functional.allcomplextypes a, a", "Illegal table reference to non-collection type: 'a'");
    // Invalid reference to non-collection type.
    AnalysisError("select 1 from functional.allcomplextypes.int_struct_col", "Illegal table reference to non-collection type: " + "'functional.allcomplextypes.int_struct_col'\n" + "Path resolved to type: STRUCT<f1:INT,f2:INT>");
    AnalysisError("select 1 from functional.allcomplextypes a, a.int_struct_col", "Illegal table reference to non-collection type: 'a.int_struct_col'\n" + "Path resolved to type: STRUCT<f1:INT,f2:INT>");
    AnalysisError("select 1 from functional.allcomplextypes.int_array_col.item", "Illegal table reference to non-collection type: " + "'functional.allcomplextypes.int_array_col.item'\n" + "Path resolved to type: INT");
    AnalysisError("select 1 from functional.allcomplextypes.int_array_col a, a.pos", "Illegal table reference to non-collection type: 'a.pos'\n" + "Path resolved to type: BIGINT");
    AnalysisError("select 1 from functional.allcomplextypes.int_map_col.key", "Illegal table reference to non-collection type: " + "'functional.allcomplextypes.int_map_col.key'\n" + "Path resolved to type: STRING");
    AnalysisError("select 1 from functional.allcomplextypes.int_map_col a, a.key", "Illegal table reference to non-collection type: 'a.key'\n" + "Path resolved to type: STRING");
    // Test that parent/collection joins without an ON clause analyze ok.
    for (JoinOperator joinOp : JoinOperator.values()) {
        if (joinOp.isNullAwareLeftAntiJoin())
            continue;
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s a.int_array_col b", joinOp));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s a.struct_array_col b", joinOp));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s a.int_map_col b", joinOp));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s a.struct_map_col", joinOp));
    }
}

