@Test
public void TestSlotRefPathAmbiguity() {
    addTestDb("a");
    addTestTable("create table a.a (a struct<a:struct<a:int>>)");
    // Slot path is not ambiguous.
    AnalyzesOk("select a.a.a.a.a from a.a");
    AnalyzesOk("select t.a.a.a from a.a t");
    // Slot path is not ambiguous but resolves to a struct.
    AnalysisError("select a from a.a", "Expr 'a' in select list returns a complex type 'STRUCT<a:STRUCT<a:INT>>'.\n" + "Only scalar types are allowed in the select list.");
    AnalysisError("select t.a from a.a t", "Expr 't.a' in select list returns a complex type 'STRUCT<a:STRUCT<a:INT>>'.\n" + "Only scalar types are allowed in the select list.");
    AnalysisError("select t.a.a from a.a t", "Expr 't.a.a' in select list returns a complex type 'STRUCT<a:INT>'.\n" + "Only scalar types are allowed in the select list.");
    // Slot paths are ambiguous. A slot path can legally resolve to a non-scalar type,
    // even though we currently do not support non-scalar SlotRefs in the select list
    // or in any exprs.
    AnalysisError("select a.a from a.a", "Column/field reference is ambiguous: 'a.a'");
    AnalysisError("select a.a.a from a.a", "Column/field reference is ambiguous: 'a.a.a'");
    AnalysisError("select a.a.a.a from a.a", "Column/field reference is ambiguous: 'a.a.a.a'");
    // Cannot resolve slot paths.
    AnalysisError("select a.a.a.a.a.a from a.a", "Could not resolve column/field reference: 'a.a.a.a.a.a'");
    AnalysisError("select t.a.a.a.a from a.a t", "Could not resolve column/field reference: 't.a.a.a.a'");
    // Paths resolve to an existing implicit table alias
    // (the unqualified path resolution would be illegal).
    addTestTable("create table a.array_test (a array<int>)");
    addTestTable("create table a.map_test (a map<int, int>)");
    AnalyzesOk("select a.item from a.array_test t, t.a");
    AnalyzesOk("select a.key, a.value from a.map_test t, t.a");
}

@Test
public void TestStarPathAmbiguity() {
    addTestDb("a");
    addTestTable("create table a.a (a struct<a:struct<a:int>>)");
    // Star path is not ambiguous.
    AnalyzesOk("select a.a.a.a.* from a.a");
    AnalyzesOk("select t.a.a.* from a.a t");
    // Not ambiguous, but illegal.
    AnalysisError("select a.a.a.a.a.* from a.a", "Cannot expand star in 'a.a.a.a.a.*' because path 'a.a.a.a.a' " + "resolved to type 'INT'.");
    AnalysisError("select t.a.a.a.* from a.a t", "Cannot expand star in 't.a.a.a.*' because path 't.a.a.a' " + "resolved to type 'INT'.");
    // Not ambiguous, but expands to an empty select list.
    AnalysisError("select t.* from a.a t", "The star exprs expanded to an empty select list because the referenced " + "tables only have complex-typed columns.");
    // Star paths are ambiguous.
    AnalysisError("select a.* from a.a", "Star expression is ambiguous: 'a.*'");
    AnalysisError("select a.a.* from a.a", "Star expression is ambiguous: 'a.a.*'");
    AnalysisError("select a.a.a.* from a.a", "Star expression is ambiguous: 'a.a.a.*'");
    // Cannot resolve star paths.
    AnalysisError("select a.a.a.a.a.a.* from a.a", "Could not resolve star expression: 'a.a.a.a.a.a.*'");
    AnalysisError("select t.a.a.a.a.* from a.a t", "Could not resolve star expression: 't.a.a.a.a.*'");
    // Paths resolve to an existing implicit table alias
    // (the unqualified path resolution would be illegal).
    addTestTable("create table a.array_test (a array<int>)");
    addTestTable("create table a.map_test (a map<int, int>)");
    AnalyzesOk("select a.* from a.array_test t, t.a");
    AnalyzesOk("select a.* from a.map_test t, t.a");
}

@Test
public void TestTableRefPathAmbiguity() {
    addTestDb("a");
    addTestTable("create table a.a (a array<struct<a:array<int>>>)");
    // Table paths are not ambiguous.
    AnalyzesOk("select 1 from a.a");
    AnalyzesOk("select 1 from a.a.a");
    AnalyzesOk("select 1 from a.a.a.a");
    AnalyzesOk("select 1 from a", createAnalyzer("a"));
