/**
 * Tests the visibility of semi-/anti-joined table references.
 */
@Test
public void TestSemiJoins() {
    // Test left semi joins.
    for (String joinType : new String[] { "left semi join", "left anti join" }) {
        // semi/anti join requires ON/USING clause
        AnalyzesOk(String.format("select a.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType));
        AnalyzesOk(String.format("select a.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id) " + "%s functional.alltypes c on (a.id = c.id)", joinType, joinType));
        AnalyzesOk(String.format("select a.id from functional.alltypes a %s " + "functional.alltypes b using (id)", joinType));
        // unqualified column reference is not ambiguous outside of the On-clause
        // because a semi/anti-joined tuple is invisible
        AnalyzesOk(String.format("select int_col from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType));
        AnalysisError(String.format("select * from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id and a.int_col = int_col)", joinType), "Column/field reference is ambiguous: 'int_col'");
        // flip 'a' and 'b' aliases to test the unqualified column resolution logic
        AnalyzesOk(String.format("select int_col from functional.alltypes b " + "%s functional.alltypes a on (b.id = a.id)", joinType));
        AnalysisError(String.format("select * from functional.alltypes b " + "%s functional.alltypes a on (b.id = a.id and b.int_col = int_col)", joinType), "Column/field reference is ambiguous: 'int_col'");
        // unqualified column reference that matches two semi-/anti-joined tables
        // is not ambiguous outside of On-clause
        AnalyzesOk(String.format("select int_col from functional.alltypes c " + "%s functional.alltypes b on (c.id = b.id) " + "%s functional.jointbl a on (test_id = c.id)", joinType, joinType));
        AnalyzesOk(String.format("select int_col from functional.alltypes c " + "%s functional.alltypes b on (c.id = b.id) " + "%s functional.jointbl a on (test_id = id)", joinType, joinType));
        AnalysisError(String.format("select int_col from functional.alltypes c " + "%s functional.alltypes b on (c.id = b.id) " + "%s functional.jointbl a on (test_id = b.id)", joinType, joinType), "Illegal column/field reference 'b.id' of semi-/anti-joined table 'b'");
        // must not reference semi/anti-joined alias outside of join clause
        AnalysisError(String.format("select a.id, b.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType), "Illegal column/field reference 'b.id' of semi-/anti-joined table 'b'");
        AnalysisError(String.format("select a.id from functional.alltypes a " + "%s (select * from functional.alltypes) b " + "on (a.id = b.id) where b.int_col > 10", joinType), "Illegal column/field reference 'b.int_col' of semi-/anti-joined table 'b'");
        AnalysisError(String.format("select a.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id) group by b.bool_col", joinType), "Illegal column/field reference 'b.bool_col' of semi-/anti-joined table 'b'");
        AnalysisError(String.format("select a.id from functional.alltypes a " + "%s (select * from functional.alltypes) b " + "on (a.id = b.id) order by b.string_col", joinType), "Illegal column/field reference 'b.string_col' of " + "semi-/anti-joined table 'b'");
        // column of semi/anti-joined table is not visible in other On-clause
        AnalysisError(String.format("select a.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)" + "left outer join functional.testtbl c on (b.id = c.id)", joinType), "Illegal column/field reference 'b.id' of semi-/anti-joined table 'b'");
        // column of semi/anti-joined table is not visible in other On-clause
        AnalysisError(String.format("select a.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)" + "%s functional.testtbl c on (b.id = c.id)", joinType, joinType), "Illegal column/field reference 'b.id' of semi-/anti-joined table 'b'");
        // using clause always refers to lhs/rhs table
        AnalysisError(String.format("select a.id from functional.alltypes a " + "%s functional.alltypes b using(id) " + "%s functional.alltypes c using(int_col)", joinType, joinType), "Illegal column/field reference 'b.int_col' of semi-/anti-joined table 'b'");
        // unqualified column reference is ambiguous in the On-clause of a semi/anti join
        AnalysisError(String.format("select * from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id and a.int_col = int_col)", joinType), "Column/field reference is ambiguous: 'int_col'");
        // illegal unqualified column reference against semi/anti-joined table
        AnalysisError(String.format("select test_id from functional.alltypes a " + "%s functional.jointbl b on (a.id = b.alltypes_id)", joinType), "Illegal column/field reference 'test_id' of semi-/anti-joined table 'b'");
        // unqualified table ref is ambiguous even if semi/anti-joined
        AnalysisError(String.format("select alltypes.int_col from functional.alltypes " + "%s functional_parquet.alltypes " + "on (functional.alltypes.id = functional_parquet.alltypes.id)", joinType), "Unqualified table alias is ambiguous: 'alltypes'");
        // illegal collection table reference through semi/anti joined table
        AnalysisError(String.format("select 1 from functional.allcomplextypes a " + "%s functional.allcomplextypes b on (a.id = b.id) " + "inner join b.int_array_col", joinType), "Illegal table reference 'b.int_array_col' of semi-/anti-joined table 'b'");
    }
    // Test right semi joins. Do not combine these with the left semi join tests above
    // for better readability.
    for (String joinType : new String[] { "right semi join", "right anti join" }) {
        // semi/anti join requires ON/USING clause
        AnalyzesOk(String.format("select b.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType));
        AnalyzesOk(String.format("select c.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id) " + "%s functional.alltypes c on (b.id = c.id)", joinType, joinType));
        AnalyzesOk(String.format("select b.id from functional.alltypes a %s " + "functional.alltypes b using (id)", joinType));
        // unqualified column reference is not ambiguous outside of the On-clause
        // because a semi/anti-joined tuple is invisible
        AnalyzesOk(String.format("select int_col from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType));
        AnalysisError(String.format("select * from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id and a.int_col = int_col)", joinType), "Column/field reference is ambiguous: 'int_col'");
        // flip 'a' and 'b' aliases to test the unqualified column resolution logic
        AnalyzesOk(String.format("select int_col from functional.alltypes b " + "%s functional.alltypes a on (b.id = a.id)", joinType));
        AnalysisError(String.format("select * from functional.alltypes b " + "%s functional.alltypes a on (b.id = a.id and b.int_col = int_col)", joinType), "Column/field reference is ambiguous: 'int_col'");
        // unqualified column reference that matches two semi-/anti-joined tables
        // is not ambiguous outside of On-clause
        AnalyzesOk(String.format("select int_col from functional.jointbl c " + "%s functional.alltypes b on (test_id = b.id) " + "%s functional.alltypes a on (b.id = a.id)", joinType, joinType));
        AnalyzesOk(String.format("select int_col from functional.jointbl c " + "%s functional.alltypes b on (test_id = id) " + "%s functional.alltypes a on (b.id = a.id)", joinType, joinType));
        AnalysisError(String.format("select int_col from functional.jointbl c " + "%s functional.alltypes b on (test_id = a.id) " + "%s functional.alltypes a on (c.id = b.id)", joinType, joinType), "Could not resolve column/field reference: 'a.id'");
        // must not reference semi/anti-joined alias outside of join clause
        AnalysisError(String.format("select a.id, b.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)", joinType), "Illegal column/field reference 'a.id' of semi-/anti-joined table 'a'");
        AnalysisError(String.format("select b.id from functional.alltypes a " + "%s (select * from functional.alltypes) b " + "on (a.id = b.id) where a.int_col > 10", joinType), "Illegal column/field reference 'a.int_col' of semi-/anti-joined table 'a'");
        AnalysisError(String.format("select b.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id) group by a.bool_col", joinType), "Illegal column/field reference 'a.bool_col' of semi-/anti-joined table 'a'");
        AnalysisError(String.format("select b.id from functional.alltypes a " + "%s (select * from functional.alltypes) b " + "on (a.id = b.id) order by a.string_col", joinType), "Illegal column/field reference 'a.string_col' of " + "semi-/anti-joined table 'a'");
        // column of semi/anti-joined table is not visible in other On-clause
        AnalysisError(String.format("select b.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)" + "left outer join functional.testtbl c on (a.id = c.id)", joinType), "Illegal column/field reference 'a.id' of semi-/anti-joined table 'a'");
        // column of semi/anti-joined table is not visible in other On-clause
        AnalysisError(String.format("select b.id from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id)" + "%s functional.testtbl c on (a.id = c.id)", joinType, joinType), "Illegal column/field reference 'a.id' of semi-/anti-joined table 'a'");
        // using clause always refers to lhs/rhs table
        AnalysisError(String.format("select b.id from functional.alltypes a " + "%s functional.alltypes b using(id) " + "%s functional.alltypes c using(int_col)", joinType, joinType), "Illegal column/field reference 'b.id' of semi-/anti-joined table 'b'");
        // unqualified column reference is ambiguous in the On-clause of a semi/anti join
        AnalysisError(String.format("select * from functional.alltypes a " + "%s functional.alltypes b on (a.id = b.id and a.int_col = int_col)", joinType), "Column/field reference is ambiguous: 'int_col'");
        // illegal unqualified column reference against semi/anti-joined table
        AnalysisError(String.format("select test_id from functional.jointbl a " + "%s functional.alltypes b on (a.alltypes_id = b.id)", joinType), "Illegal column/field reference 'test_id' of semi-/anti-joined table 'a'");
        // unqualified table ref is ambiguous even if semi/anti-joined
        AnalysisError(String.format("select alltypes.int_col from functional.alltypes " + "%s functional_parquet.alltypes " + "on (functional.alltypes.id = functional_parquet.alltypes.id)", joinType), "Unqualified table alias is ambiguous: 'alltypes'");
        // illegal collection table reference through semi/anti joined table
        AnalysisError(String.format("select 1 from functional.allcomplextypes a " + "%s functional.allcomplextypes b on (a.id = b.id) " + "inner join a.int_array_col", joinType), "Illegal table reference 'a.int_array_col' of semi-/anti-joined table 'a'");
    }
}

@Test
public void TestJoinHints() throws AnalysisException {
    String[][] hintStyles = new String[][] { // traditional commented hint
    new String[] { "/* +", "*/" }, // eol commented hint
    new String[] { "\n-- +", "\n" }, // legacy style
    new String[] { "[", "]" } };
    for (String[] hintStyle : hintStyles) {
        String prefix = hintStyle[0];
        String suffix = hintStyle[1];
        AnalyzesOk(String.format("select * from functional.alltypes a join %sbroadcast%s " + "functional.alltypes b using (int_col)", prefix, suffix));
        AnalyzesOk(String.format("select * from functional.alltypes a join %sshuffle%s " + "functional.alltypes b using (int_col)", prefix, suffix));
        AnalyzesOk(String.format("select * from functional.alltypes a cross join %sbroadcast%s " + "functional.alltypes b", prefix, suffix));
        // Only warn on unrecognized hints for view-compatibility with Hive.
        AnalyzesOk(String.format("select * from functional.alltypes a join %sbadhint%s " + "functional.alltypes b using (int_col)", prefix, suffix), "JOIN hint not recognized: badhint");
        // Hints must be comma separated. Legacy-style hint does not parse because
        // of space-separated identifiers.
        if (!prefix.contains("[")) {
            AnalyzesOk(String.format("select * from functional.alltypes a join %sbroadcast broadcast%s " + "functional.alltypes b using (int_col)", prefix, suffix), "JOIN hint not recognized: broadcast broadcast");
        }
        AnalysisError(String.format("select * from functional.alltypes a cross join %sshuffle%s " + "functional.alltypes b", prefix, suffix), "CROSS JOIN does not support SHUFFLE.");
        AnalysisError(String.format("select * from functional.alltypes a right outer join %sbroadcast%s " + "functional.alltypes b using (int_col)", prefix, suffix), "RIGHT OUTER JOIN does not support BROADCAST.");
        AnalysisError(String.format("select * from functional.alltypes a full outer join %sbroadcast%s " + "functional.alltypes b using (int_col)", prefix, suffix), "FULL OUTER JOIN does not support BROADCAST.");
        AnalysisError(String.format("select * from functional.alltypes a right semi join %sbroadcast%s " + "functional.alltypes b using (int_col)", prefix, suffix), "RIGHT SEMI JOIN does not support BROADCAST.");
        AnalysisError(String.format("select * from functional.alltypes a right anti join %sbroadcast%s " + "functional.alltypes b using (int_col)", prefix, suffix), "RIGHT ANTI JOIN does not support BROADCAST.");
        // Conflicting join hints.
        AnalysisError(String.format("select * from functional.alltypes a join %sbroadcast,shuffle%s " + "functional.alltypes b using (int_col)", prefix, suffix), "Conflicting JOIN hint: shuffle");
    }
}

