}

@Test
public void TestAggregates() throws AnalysisException {
    // Add udas:
    //   bigint AggFn(int)
    //   bigint AggFn(bigint)
    //   bigint AggFn(double)
    //   string AggFn(string, string)
    // TODO: if we could persist these in the catalog, we'd just use those
    // TODO: add cases where the intermediate type is not the return type when
    // the planner supports that.
    addTestUda("AggFn", Type.BIGINT, Type.INT);
    addTestUda("AggFn", Type.BIGINT, Type.BIGINT);
    addTestUda("AggFn", Type.BIGINT, Type.DOUBLE);
    addTestUda("AggFn", Type.STRING, Type.STRING, Type.STRING);
    AnalyzesOk("select aggfn(int_col) from functional.alltypesagg");
    AnalysisError("select default.AggFn(1)", "aggregation without a FROM clause is not allowed");
    AnalysisError("select aggfn(int_col) over (partition by int_col) from functional.alltypesagg", "Aggregate function 'default.aggfn(int_col)' not supported with OVER clause.");
    AnalysisError("select aggfn(distinct int_col) from functional.alltypesagg", "User defined aggregates do not support DISTINCT.");
    AnalyzesOk("select default.aggfn(int_col) from functional.alltypes");
    AnalyzesOk("select count(*) from functional.testtbl");
    AnalyzesOk("select min(id), max(id), sum(id) from functional.testtbl");
    AnalyzesOk("select avg(id) from functional.testtbl");
    AnalyzesOk("select count(*), min(id), max(id), sum(id), avg(id), aggfn(id) " + "from functional.testtbl");
    AnalyzesOk("select AggFn(tinyint_col), AggFn(int_col), AggFn(bigint_col), " + "AggFn(double_col) from functional.alltypes");
    AnalysisError("select AggFn(string_col) from functional.alltypes", "No matching function with signature: default.aggfn(STRING)");
    AnalyzesOk("select AggFn(string_col, string_col) from functional.alltypes");
    AnalyzesOk("select count(NULL), min(NULL), max(NULL), sum(NULL), avg(NULL), " + "group_concat(NULL), group_concat(name, NULL) from functional.testtbl");
    AnalysisError("select id, zip from functional.testtbl where count(*) > 0", "aggregate function not allowed in WHERE clause");
    AnalysisError("select 1 from functional.alltypes where aggfn(1)", "aggregate function not allowed in WHERE clause");
    AnalysisError("select count() from functional.alltypes", "count() is not allowed.");
    AnalysisError("select min() from functional.alltypes", "No matching function with signature: min().");
    AnalysisError("select int_col from functional.alltypes order by count(*)", "select list expression not produced by aggregation output (missing from " + "GROUP BY clause?): int_col");
    AnalysisError("select functional.alltypes.*, max(string_col) from " + "functional.alltypes", "cannot combine '*' in select list with grouping or " + "aggregation");
    // only count() allows '*'
    AnalysisError("select avg(*) from functional.testtbl", "'*' can only be used in conjunction with COUNT");
    AnalysisError("select min(*) from functional.testtbl", "'*' can only be used in conjunction with COUNT");
    AnalysisError("select max(*) from functional.testtbl", "'*' can only be used in conjunction with COUNT");
    // multiple args
    AnalysisError("select count(id, zip) from functional.testtbl", "COUNT must have DISTINCT for multiple arguments: count(id, zip)");
    AnalysisError("select min(id, zip) from functional.testtbl", "No matching function with signature: min(BIGINT, INT).");
    // nested aggregates
    AnalysisError("select sum(count(*)) from functional.testtbl", "aggregate function must not contain aggregate parameters");
    AnalysisError("select sum(rank() over (order by id)) from functional.testtbl", "aggregate function must not contain analytic parameters");
    AnalysisError("select min(aggfn(int_col)) from functional.alltypes", "aggregate function must not contain aggregate parameters: " + "min(default.aggfn(int_col))");
    // wrong type
    AnalysisError("select sum(timestamp_col) from functional.alltypes", "SUM requires a numeric parameter: sum(timestamp_col)");
    AnalysisError("select sum(string_col) from functional.alltypes", "SUM requires a numeric parameter: sum(string_col)");
    AnalysisError("select avg(string_col) from functional.alltypes", "AVG requires a numeric or timestamp parameter: avg(string_col)");
    // aggregate requires table in the FROM clause
    AnalysisError("select count(*)", "aggregation without a FROM clause is not allowed");
    AnalysisError("select min(1)", "aggregation without a FROM clause is not allowed");
    // Test distinct estimate
    for (Type type : typeToLiteralValue_.keySet()) {
        AnalyzesOk(String.format("select ndv(%s) from functional.alltypes", typeToLiteralValue_.get(type)));
    }
    // Decimal
    AnalyzesOk("select min(d1), max(d2), count(d3), sum(d4) " + "from functional.decimal_tbl");
    AnalyzesOk("select ndv(d1), distinctpc(d2), distinctpcsa(d3), count(distinct d4) " + "from functional.decimal_tbl");
    AnalyzesOk("select avg(d5) from functional.decimal_tbl");
    // Test select stmt avg smap.
    AnalyzesOk("select cast(avg(c1) as decimal(10,4)) as c from " + "functional.decimal_tiny group by c3 having c = 5.1106 order by 1");
    // check CHAR and VARCHAR aggregates
    checkExprType("select min(cast('foo' as char(5))) from functional.chars_tiny", ScalarType.STRING);
    checkExprType("select max(cast('foo' as varchar(5))) from functional.chars_tiny", ScalarType.STRING);
    checkExprType("select max(vc) from functional.chars_tiny", ScalarType.STRING);
    checkExprType("select max(cs) from functional.chars_tiny", ScalarType.STRING);
    checkExprType("select max(lower(cs)) from functional.chars_tiny", ScalarType.STRING);
}

@Test
public void TestDistinct() throws AnalysisException {
    AnalyzesOk("select count(distinct id) as sum_id from functional.testtbl");
    AnalyzesOk("select count(distinct id) as sum_id from " + "functional.testtbl order by sum_id");
    AnalyzesOk("select count(distinct id) as sum_id from " + "functional.testtbl order by max(id)");
    AnalyzesOk("select distinct id, zip from functional.testtbl");
    AnalyzesOk("select distinct * from functional.testtbl");
    AnalysisError("select distinct count(*) from functional.testtbl", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalysisError("select distinct id, zip from functional.testtbl group by 1, 2", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalysisError("select distinct id, zip, count(*) from " + "functional.testtbl group by 1, 2", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalyzesOk("select distinct id from functional.testtbl having id > 0");
    AnalysisError("select distinct id from functional.testtbl having max(id) > 0", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalyzesOk("select count(distinct id, zip) from functional.testtbl");
    AnalysisError("select count(distinct id, zip), count(distinct zip) " + "from functional.testtbl", "all DISTINCT aggregate functions need to have the same set of parameters");
    AnalyzesOk("select tinyint_col, count(distinct int_col, bigint_col) " + "from functional.alltypesagg group by 1");
    AnalyzesOk("select tinyint_col, count(distinct int_col)," + "sum(distinct int_col) from functional.alltypesagg group by 1");
    AnalyzesOk("select avg(DISTINCT(tinyint_col)) from functional.alltypesagg");
    // SUM(DISTINCT) and AVG(DISTINCT) with duplicate grouping exprs (IMPALA-847).
    AnalyzesOk("select sum(distinct t1.bigint_col), avg(distinct t1.bigint_col) " + "from functional.alltypes t1 group by t1.int_col, t1.int_col");
    AnalysisError("select tinyint_col, count(distinct int_col)," + "sum(distinct bigint_col) from functional.alltypesagg group by 1", "all DISTINCT aggregate functions need to have the same set of parameters");
    // min and max are ignored in terms of DISTINCT
    AnalyzesOk("select tinyint_col, count(distinct int_col)," + "min(distinct smallint_col), max(distinct string_col) " + "from functional.alltypesagg group by 1");
}

