    AnalyzesOk("select group_concat(distinct name, cast(123 as string)) " + "from functional.testtbl");
    AnalysisError("select group_concat(distinct name, cast(id as string)) " + "from functional.testtbl", "Second parameter in GROUP_CONCAT(DISTINCT) must be a constant expression" + " that returns a string.");
    AnalyzesOk("select group_concat(distinct string_col, concat('-', '?')) " + "from functional.alltypesagg");
    AnalysisError("select group_concat(*) from functional.testtbl", "'*' can only be used in conjunction with COUNT");
    // test group_concat using a column as the custom separator
    AnalyzesOk("select group_concat(string_col, string_col) from functional.alltypes");
    // test group_concat without and with distinct
    String[] keywords = new String[] { "distinct", "" };
    for (String keyword : keywords) {
        AnalysisError(String.format("select group_concat(%s '')", keyword), "aggregation" + " without a FROM clause is not allowed");
        AnalysisError(String.format("select group_concat(%s name, '-', ',') " + "from functional.testtbl", keyword), "No matching function with signature: " + "group_concat(STRING, STRING, STRING)");
        // test all types as arguments
        for (Type type : typeToLiteralValue_.keySet()) {
            String literal = typeToLiteralValue_.get(type);
            String query1 = String.format("select group_concat(%s %s) from functional.alltypes", keyword, literal);
            String query2 = String.format("select group_concat(%s %s, '---') from functional.alltypes", keyword, literal);
            if (type.getPrimitiveType() == PrimitiveType.STRING || type.isNull()) {
                AnalyzesOk(query1);
                AnalyzesOk(query2);
            } else {
                AnalysisError(query1, "No matching function with signature: group_concat(");
                AnalysisError(query2, "No matching function with signature: group_concat(");
            }
        }
    }
}

@Test
public void TestDistinctInlineView() throws AnalysisException {
    // DISTINCT
    AnalyzesOk("select distinct id from " + "(select distinct id, zip from (select * from functional.testtbl) x) y");
    AnalyzesOk("select distinct * from " + "(select distinct * from (Select * from functional.testtbl) x) y");
    AnalyzesOk("select distinct * from (select count(*) from functional.testtbl) x");
