    AnalysisError("select * from " + "(select count(distinct id, zip), count(distinct zip) " + "from functional.testtbl) x", "all DISTINCT aggregate functions need to have the same set of parameters");
    AnalysisError("select * from " + "(select tinyint_col, count(distinct int_col)," + "sum(distinct bigint_col) from functional.alltypesagg group by 1) x", "all DISTINCT aggregate functions need to have the same set of parameters");
    // Error case when inline view is in the from clause
    AnalysisError("select distinct count(*) from (select * from functional.testtbl) x", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalysisError("select distinct id, zip from " + "(select * from functional.testtbl) x group by 1, 2", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalysisError("select distinct id, zip, count(*) from " + "(select * from functional.testtbl) x group by 1, 2", "cannot combine SELECT DISTINCT with aggregate functions or GROUP BY");
    AnalyzesOk("select count(distinct id, zip) " + "from (select * from functional.testtbl) x");
    AnalysisError("select count(distinct id, zip), count(distinct zip) " + " from (select * from functional.testtbl) x", "all DISTINCT aggregate functions need to have the same set of parameters");
    AnalyzesOk("select tinyint_col, count(distinct int_col, bigint_col) " + "from (select * from functional.alltypesagg) x group by 1");
    AnalyzesOk("select tinyint_col, count(distinct int_col)," + "sum(distinct int_col) from " + "(select * from functional.alltypesagg) x group by 1");
    AnalysisError("select tinyint_col, count(distinct int_col)," + "sum(distinct bigint_col) from " + "(select * from functional.alltypesagg) x group by 1", "all DISTINCT aggregate functions need to have the same set of parameters");
}

@Test
public void TestGroupBy() throws AnalysisException {
    AnalyzesOk("select zip, count(*) from functional.testtbl group by zip");
    AnalyzesOk("select zip + count(*) from functional.testtbl group by zip");
    // grouping on constants is ok and doesn't require them to be in select list
    AnalyzesOk("select count(*) from functional.testtbl group by 2*3+4");
    AnalyzesOk("select count(*) from functional.testtbl " + "group by true, false, NULL");
    // ok for constants in select list not to be in group by list
    AnalyzesOk("select true, NULL, 1*2+5 as a, zip, count(*) from functional.testtbl " + "group by zip");
    AnalyzesOk("select d1, d2, count(*) from functional.decimal_tbl " + "group by 1, 2");
    // doesn't group by all non-agg select list items
    AnalysisError("select zip, count(*) from functional.testtbl", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
    AnalysisError("select zip + count(*) from functional.testtbl", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
    // test having clause
    AnalyzesOk("select id, zip from functional.testtbl " + "group by zip, id having count(*) > 0");
    AnalyzesOk("select count(*) from functional.alltypes " + "group by bool_col having bool_col");
    // arbitrary exprs not returning boolean
    AnalysisError("select count(*) from functional.alltypes " + "group by bool_col having 5 + 10 * 5.6", "HAVING clause '5 + 10 * 5.6' requires return type 'BOOLEAN'. " + "Actual type is 'DOUBLE'.");
    AnalysisError("select count(*) from functional.alltypes " + "group by bool_col having int_col", "HAVING clause 'int_col' requires return type 'BOOLEAN'. Actual type is 'INT'.");
    AnalysisError("select id, zip from functional.testtbl " + "group by id having count(*) > 0", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
    AnalysisError("select id from functional.testtbl " + "group by id having zip + count(*) > 0", "HAVING clause not produced by aggregation output " + "(missing from GROUP BY clause?)");
    // resolves ordinals
    AnalyzesOk("select zip, count(*) from functional.testtbl group by 1");
    AnalyzesOk("select count(*), zip from functional.testtbl group by 2");
    AnalysisError("select zip, count(*) from functional.testtbl group by 3", "GROUP BY: ordinal exceeds number of items in select list: 3");
    AnalysisError("select * from functional.alltypes group by 1", "cannot combine '*' in select list with grouping or aggregation");
    // picks up select item alias
    AnalyzesOk("select zip z, id iD1, id ID2, count(*) " + "from functional.testtbl group by z, ID1, id2");
    // same alias is not ambiguous if it refers to the same expr
    AnalyzesOk("select int_col, INT_COL from functional.alltypes group by int_col");
    AnalyzesOk("select bool_col a, bool_col A from functional.alltypes group by a");
    AnalyzesOk("select int_col A, bool_col b, int_col a, bool_col B " + "from functional.alltypes group by a, b");
    // ambiguous alias
    AnalysisError("select zip a, id a, count(*) from functional.testtbl group by a", "Column 'a' in GROUP BY clause is ambiguous");
    AnalysisError("select zip id, id, count(*) from functional.testtbl group by id", "Column 'id' in GROUP BY clause is ambiguous");
    // can't group by aggregate
    AnalysisError("select zip, count(*) from functional.testtbl group by count(*)", "GROUP BY expression must not contain aggregate functions");
    AnalysisError("select zip, count(*) " + "from functional.testtbl group by count(*) + min(zip)", "GROUP BY expression must not contain aggregate functions");
    AnalysisError("select zip, count(*) from functional.testtbl group by 2", "GROUP BY expression must not contain aggregate functions");
    // multiple grouping cols
    AnalyzesOk("select int_col, string_col, bigint_col, count(*) " + "from functional.alltypes group by string_col, int_col, bigint_col");
    AnalyzesOk("select int_col, string_col, bigint_col, count(*) " + "from functional.alltypes group by 2, 1, 3");
    AnalysisError("select int_col, string_col, bigint_col, count(*) " + "from functional.alltypes group by 2, 1, 4", "GROUP BY expression must not contain aggregate functions");
    // group by floating-point column
    AnalyzesOk("select float_col, double_col, count(*) " + "from functional.alltypes group by 1, 2");
    // group by floating-point exprs
    AnalyzesOk("select int_col + 0.5, count(*) from functional.alltypes group by 1");
    AnalyzesOk("select cast(int_col as double), count(*)" + "from functional.alltypes group by 1");
    // select expression refers to column with same name as its own explicit alias and
    // it's referred to by ordinal in group by (IMPALA-1898)
    // Trivial example
    AnalyzesOk("select bigint_col + 0 AS bigint_col, sum(smallint_col) " + "FROM functional.alltypes " + "GROUP BY 1");
    // More complex example
    AnalyzesOk("select extract(timestamp_col, 'hour') AS timestamp_col, string_col, " + "sum(double_col) AS double_total " + "FROM functional.alltypes " + "GROUP BY 1, 2");
}

@Test
public void TestOrderBy() throws AnalysisException {
    AnalyzesOk("select zip, id from functional.testtbl order by zip");
    AnalyzesOk("select zip, id from functional.testtbl order by zip asc");
    AnalyzesOk("select zip, id from functional.testtbl order by zip desc");
    AnalyzesOk("select zip, id from functional.testtbl " + "order by true asc, false desc, NULL asc");
    AnalyzesOk("select d1, d2 from functional.decimal_tbl order by d1");
    // resolves ordinals
    AnalyzesOk("select zip, id from functional.testtbl order by 1");
    AnalyzesOk("select zip, id from functional.testtbl order by 2 desc, 1 asc");
    // ordinal out of range
    AnalysisError("select zip, id from functional.testtbl order by 0", "ORDER BY: ordinal must be >= 1");
    AnalysisError("select zip, id from functional.testtbl order by 3", "ORDER BY: ordinal exceeds number of items in select list: 3");
    AnalyzesOk("select * from functional.alltypes order by 1");
    // picks up select item alias
    AnalyzesOk("select zip z, id C, id D from functional.testtbl order by z, C, d");
    // can introduce additional aggregates in order by clause
    AnalyzesOk("select zip, count(*) from functional.testtbl group by 1 " + " order by count(*)");
    AnalyzesOk("select zip, count(*) from functional.testtbl " + "group by 1 order by count(*) + min(zip)");
    AnalysisError("select zip, count(*) from functional.testtbl group by 1 order by id", "ORDER BY expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
    // multiple ordering exprs
    AnalyzesOk("select int_col, string_col, bigint_col from functional.alltypes " + "order by string_col, 15.7 * float_col, int_col + bigint_col");
    AnalyzesOk("select int_col, string_col, bigint_col from functional.alltypes " + "order by 2, 1, 3");
    // ordering by floating-point exprs is okay
    AnalyzesOk("select float_col, int_col + 0.5 from functional.alltypes order by 1, 2");
    AnalyzesOk("select float_col, int_col + 0.5 from functional.alltypes order by 2, 1");
    // select-list item takes precedence
    AnalyzesOk("select t1.int_col from functional.alltypes t1, " + "functional.alltypes t2 where t1.id = t2.id order by int_col");
    // same alias is not ambiguous if it refers to the same expr
    AnalyzesOk("select int_col, INT_COL from functional.alltypes order by int_col");
    AnalyzesOk("select bool_col a, bool_col A from functional.alltypes order by a");
    AnalyzesOk("select int_col A, bool_col b, int_col a, bool_col B " + "from functional.alltypes order by a, b");
    // ambiguous alias causes error
    AnalysisError("select string_col a, int_col a from " + "functional.alltypessmall order by a limit 1", "Column 'a' in ORDER BY clause is ambiguous");
    AnalysisError("select string_col a, int_col A from " + "functional.alltypessmall order by a limit 1", "Column 'a' in ORDER BY clause is ambiguous");
    // Test if an ignored order by produces the expected warning.
    AnalyzesOk("select * from (select * from functional.alltypes order by int_col) A", "Ignoring ORDER BY clause without LIMIT or OFFSET: " + "ORDER BY int_col ASC");
    AnalyzesOk("select * from functional.alltypes order by int_col desc union all " + "select * from functional.alltypes", "Ignoring ORDER BY clause without LIMIT or OFFSET: " + "ORDER BY int_col DESC");
    AnalyzesOk("insert into functional.alltypes partition (year, month) " + "select * from functional.alltypes order by int_col", "Ignoring ORDER BY clause without LIMIT or OFFSET: " + "ORDER BY int_col ASC");
    AnalyzesOk("create table functional.alltypescopy as " + "select * from functional.alltypes order by int_col", "Ignoring ORDER BY clause without LIMIT or OFFSET: " + "ORDER BY int_col ASC");
    // select expression refers to column with same name as its own explicit alias and
    // it's referred to by ordinal in group by (IMPALA-1898)
    AnalyzesOk("select extract(timestamp_col, 'hour') AS timestamp_col " + "FROM functional.alltypes " + "ORDER BY timestamp_col");
    // Ordering by complex-typed expressions is not allowed.
    AnalysisError("select * from functional_parquet.allcomplextypes " + "order by int_struct_col", "ORDER BY expression 'int_struct_col' with " + "complex type 'STRUCT<f1:INT,f2:INT>' is not supported.");
    AnalysisError("select * from functional_parquet.allcomplextypes " + "order by int_array_col", "ORDER BY expression 'int_array_col' with " + "complex type 'ARRAY<INT>' is not supported.");
}

@Test
public void TestUnion() {
    // Selects on different tables.
    AnalyzesOk("select rank() over (order by int_col) from functional.alltypes union " + "select int_col from functional.alltypessmall");
    // Selects on same table without aliases.
    AnalyzesOk("select int_col from functional.alltypes union " + "select int_col from functional.alltypes");
    // Longer union chain.
    AnalyzesOk("select int_col from functional.alltypes union " + "select int_col from functional.alltypes " + "union select int_col from functional.alltypes union " + "select int_col from functional.alltypes");
    // All columns, perfectly compatible.
    AnalyzesOk("select id, bool_col, tinyint_col, smallint_col, int_col, bigint_col, " + "float_col, double_col, date_string_col, string_col, timestamp_col, year," + "month from functional.alltypes union " + "select id, bool_col, tinyint_col, smallint_col, int_col, bigint_col, " + "float_col, double_col, date_string_col, string_col, timestamp_col, year," + "month from functional.alltypes");
    // Make sure table aliases aren't visible across union operands.
    AnalyzesOk("select a.smallint_col from functional.alltypes a " + "union select a.int_col from functional.alltypessmall a");
    // All columns compatible with NULL.
    AnalyzesOk("select id, bool_col, tinyint_col, smallint_col, int_col, bigint_col, " + "float_col, double_col, date_string_col, string_col, timestamp_col, year," + "month from functional.alltypes union " + "select NULL, NULL, NULL, NULL, NULL, NULL, " + "NULL, NULL, NULL, NULL, NULL, NULL," + "NULL from functional.alltypes");
    // No from clause. Has literals and NULLs. Requires implicit casts.
    AnalyzesOk("select 1, 2, 3 " + "union select NULL, NULL, NULL " + "union select 1.0, NULL, 3 " + "union select NULL, 10, NULL");
    // Implicit casts on integer types.
    AnalyzesOk("select tinyint_col from functional.alltypes " + "union select smallint_col from functional.alltypes " + "union select int_col from functional.alltypes " + "union select bigint_col from functional.alltypes");
    // Implicit casts on float types.
    AnalyzesOk("select float_col from functional.alltypes union " + "select double_col from functional.alltypes");
    // Implicit casts on all numeric types with two columns from each select.
    AnalyzesOk("select tinyint_col, double_col from functional.alltypes " + "union select smallint_col, float_col from functional.alltypes " + "union select int_col, bigint_col from functional.alltypes " + "union select bigint_col, int_col from functional.alltypes " + "union select float_col, smallint_col from functional.alltypes " + "union select double_col, tinyint_col from functional.alltypes");
    // With order by, offset and limit.
    AnalyzesOk("(select int_col from functional.alltypes) " + "union (select tinyint_col from functional.alltypessmall) " + "order by int_col limit 1");
    AnalyzesOk("(select int_col from functional.alltypes) " + "union (select tinyint_col from functional.alltypessmall) " + "order by int_col");
    AnalyzesOk("(select int_col from functional.alltypes) " + "union (select tinyint_col from functional.alltypessmall) " + "order by int_col offset 5");
    // Order by w/o limit is ignored in the union operand below.
    AnalyzesOk("select int_col from functional.alltypes order by int_col " + "union (select tinyint_col from functional.alltypessmall) ");
    AnalysisError("select int_col from functional.alltypes order by int_col offset 5 " + "union (select tinyint_col from functional.alltypessmall) ", "Order-by with offset without limit not supported in nested queries");
    AnalysisError("select int_col from functional.alltypes offset 5 " + "union (select tinyint_col from functional.alltypessmall) ", "OFFSET requires an ORDER BY clause: OFFSET 5");
    // Order by w/o limit is ignored in the union operand below.
    AnalyzesOk("select int_col from functional.alltypes " + "union (select tinyint_col from functional.alltypessmall " + "order by tinyint_col) ");
    AnalysisError("select int_col from functional.alltypes " + "union (select tinyint_col from functional.alltypessmall " + "order by tinyint_col offset 5) ", "Order-by with offset without limit not supported in nested queries");
    AnalysisError("select int_col from functional.alltypes " + "union (select tinyint_col from functional.alltypessmall offset 5) ", "OFFSET requires an ORDER BY clause: OFFSET 5");
    // Bigger order by.
    AnalyzesOk("(select tinyint_col, double_col from functional.alltypes) " + "union (select smallint_col, float_col from functional.alltypes) " + "union (select int_col, bigint_col from functional.alltypes) " + "union (select bigint_col, int_col from functional.alltypes) " + "order by double_col, tinyint_col");
    // Multiple union operands with valid order by clauses.
    AnalyzesOk("select int_col from functional.alltypes order by int_col " + "union select int_col from functional.alltypes order by int_col limit 10 " + "union (select int_col from functional.alltypes " + "order by int_col limit 10 offset 5) order by int_col offset 5");
    // Bigger order by with ordinals.
    AnalyzesOk("(select tinyint_col, double_col from functional.alltypes) " + "union (select smallint_col, float_col from functional.alltypes) " + "union (select int_col, bigint_col from functional.alltypes) " + "union (select bigint_col, int_col from functional.alltypes) " + "order by 2, 1");
    // Unequal number of columns.
    AnalysisError("select int_col from functional.alltypes " + "union select int_col, float_col from functional.alltypes", "Operands have unequal number of columns:\n" + "'SELECT int_col FROM functional.alltypes' has 1 column(s)\n" + "'SELECT int_col, float_col FROM functional.alltypes' has 2 column(s)");
    // Unequal number of columns, longer union chain.
    AnalysisError("select int_col from functional.alltypes " + "union select tinyint_col from functional.alltypes " + "union select smallint_col from functional.alltypes " + "union select smallint_col, bigint_col from functional.alltypes", "Operands have unequal number of columns:\n" + "'SELECT int_col FROM functional.alltypes' has 1 column(s)\n" + "'SELECT smallint_col, bigint_col FROM functional.alltypes' has 2 column(s)");
    // Incompatible types.
    AnalysisError("select bool_col from functional.alltypes " + "union select lag(string_col) over(order by int_col) from functional.alltypes", "Incompatible return types 'BOOLEAN' and 'STRING' of exprs " + "'bool_col' and 'lag(string_col, 1, NULL)'.");
    // Incompatible types, longer union chain.
    AnalysisError("select int_col, string_col from functional.alltypes " + "union select tinyint_col, bool_col from functional.alltypes " + "union select smallint_col, int_col from functional.alltypes " + "union select smallint_col, bool_col from functional.alltypes", "Incompatible return types 'STRING' and 'BOOLEAN' of " + "exprs 'string_col' and 'bool_col'.");
    // Invalid ordinal in order by.
    AnalysisError("(select int_col from functional.alltypes) " + "union (select int_col from functional.alltypessmall) order by 2", "ORDER BY: ordinal exceeds number of items in select list: 2");
    // Ambiguous order by.
    AnalysisError("(select int_col a, string_col a from functional.alltypes) " + "union (select int_col a, string_col a " + "from functional.alltypessmall) order by a", "Column 'a' in ORDER BY clause is ambiguous");
    // Ambiguous alias in the second union operand should work.
    AnalyzesOk("(select int_col a, string_col b from functional.alltypes) " + "union (select int_col a, string_col a " + "from functional.alltypessmall) order by a");
    // Ambiguous alias even though the exprs of the first operand are identical
    // (the corresponding in exprs in the other operand are different)
    AnalysisError("select int_col a, int_col a from functional.alltypes " + "union all (select 1, bigint_col from functional.alltypessmall) order by a", "Column 'a' in ORDER BY clause is ambiguous");
    // Column labels are inherited from first select block.
    // Order by references an invalid column
    AnalysisError("(select smallint_col from functional.alltypes) " + "union (select int_col from functional.alltypessmall) order by int_col", "Could not resolve column/field reference: 'int_col'");
    // Make sure table aliases aren't visible across union operands.
    AnalysisError("select a.smallint_col from functional.alltypes a " + "union select a.int_col from functional.alltypessmall", "Could not resolve column/field reference: 'a.int_col'");
    // Regression test for IMPALA-1128, union of decimal and an int type that converts
    // to the identical decimal.
    AnalyzesOk("select cast(1 as bigint) union select cast(1 as decimal(19, 0))");
}

@Test
public void TestValuesStmt() throws AnalysisException {
    // Values stmt with a single row.
    AnalyzesOk("values(1, 2, 3)");
    AnalyzesOk("select * from (values('a', NULL, 'c')) as t");
    AnalyzesOk("values(1.0, 2, NULL) union all values(1, 2.0, 3)");
    AnalyzesOk("insert overwrite table functional.alltypes " + "partition (year=2009, month=10)" + "values(1, true, 1, 1, 1, 1, 1.0, 1.0, 'a', 'a', cast(0 as timestamp))");
    AnalyzesOk("insert overwrite table functional.alltypes " + "partition (year, month) " + "values(1, true, 1, 1, 1, 1, 1.0, 1.0, 'a', 'a', cast(0 as timestamp)," + "2009, 10)");
    // Values stmt with multiple rows.
    AnalyzesOk("values((1, 2, 3), (4, 5, 6))");
    AnalyzesOk("select * from (values('a', 'b', 'c')) as t");
    AnalyzesOk("select * from (values(('a', 'b', 'c'), ('d', 'e', 'f'))) as t");
    AnalyzesOk("values((1.0, 2, NULL), (2.0, 3, 4)) union all values(1, 2.0, 3)");
    AnalyzesOk("insert overwrite table functional.alltypes " + "partition (year=2009, month=10) " + "values(" + "(1, true, 1, 1, 1, 1, 1.0, 1.0, 'a', 'a', cast(0 as timestamp))," + "(2, false, 2, 2, NULL, 2, 2.0, 2.0, 'b', 'b', cast(0 as timestamp))," + "(3, true, 3, 3, 3, 3, 3.0, 3.0, 'c', 'c', cast(0 as timestamp)))");
    AnalyzesOk("insert overwrite table functional.alltypes " + "partition (year, month) " + "values(" + "(1, true, 1, 1, 1, 1, 1.0, 1.0, 'a', 'a', cast(0 as timestamp), 2009, 10)," + "(2, false, 2, 2, NULL, 2, 2.0, 2.0, 'b', 'b', cast(0 as timestamp), 2009, 2)," + "(3, true, 3, 3, 3, 3, 3.0, 3.0, 'c', 'c', cast(0 as timestamp), 2009, 3))");
    // Test multiple aliases. Values() is like union, the column labels are 'x' and 'y'.
    AnalyzesOk("values((1 as x, 'a' as y), (2 as k, 'b' as j))");
    // Test order by, offset and limit.
    AnalyzesOk("values(1 as x, 'a') order by 2 limit 10");
    AnalyzesOk("values(1 as x, 'a' as y), (2, 'b') order by y limit 10");
    AnalyzesOk("values((1, 'a'), (2, 'b')) order by 1 limit 10");
    AnalyzesOk("values((1, 'a'), (2, 'b')) order by 2");
    AnalyzesOk("values((1, 'a'), (2, 'b')) order by 1 offset 5");
    AnalysisError("values((1, 'a'), (2, 'b')) offset 5", "OFFSET requires an ORDER BY clause: OFFSET 5");
    AnalysisError("values(1, 'a', 1.0, *)", "'*' expression in select list requires FROM clause.");
    AnalysisError("values(sum(1), 'a', 1.0)", "aggregation without a FROM clause is not allowed");
    AnalysisError("values(1, id, 2)", "Could not resolve column/field reference: 'id'");
    AnalysisError("values((1 as x, 'a' as y), (2, 'b')) order by c limit 1", "Could not resolve column/field reference: 'c'");
    AnalysisError("values((1, 2), (3, 4, 5))", "Operands have unequal number of columns:\n" + "'(1, 2)' has 2 column(s)\n" + "'(3, 4, 5)' has 3 column(s)");
    AnalysisError("values((1, 'a'), (3, 4))", "Incompatible return types 'STRING' and 'TINYINT' of exprs ''a'' and '4'");
    AnalysisError("insert overwrite table functional.alltypes " + "partition (year, month) " + "values(1, true, 'a', 1, 1, 1, 1.0, 1.0, 'a', 'a', cast(0 as timestamp)," + "2009, 10)", "Target table 'functional.alltypes' is incompatible with SELECT / PARTITION " + "expressions.\n" + "Expression ''a'' (type: STRING) is not compatible with column " + "'tinyint_col' (type: TINYINT)");
}

@Test
public void TestWithClause() throws AnalysisException {
    // Single view in WITH clause.
    AnalyzesOk("with t as (select int_col x, bigint_col y from functional.alltypes) " + "select x, y from t");
    // Single view in WITH clause with column labels.
    AnalyzesOk("with t(c1, c2) as (select int_col x, bigint_col y " + "from functional.alltypes) " + "select c1, c2 from t");
    // Single view in WITH clause with the number of column labels less than the number
    // of columns.
    AnalyzesOk("with t(c1) as (select int_col, bigint_col y " + "from functional.alltypes) " + "select c1, y from t");
    // Multiple views in WITH clause. Only one view is used.
    AnalyzesOk("with t1 as (select int_col x, bigint_col y from functional.alltypes), " + "t2 as (select 1 x, 10 y), t3 as (values(2 x, 20 y), (3, 30)), " + "t4 as (select 4 x, 40 y union all select 5, 50), " + "t5 as (select * from (values(6 x, 60 y)) as a) " + "select x, y from t3");
    // Multiple views in WITH clause with column labels. Only one view is used.
    AnalyzesOk("with t1(c1, c2) as (select int_col, bigint_col " + "from functional.alltypes), " + "t2(c1, c2) as (select 1, 10), t3(a, b) as (values(2, 5), (3, 30)), " + "t4(c1, c2) as (select 4, 40 union all select 5, 50), " + "t5 as (select * from (values(6, 60)) as a) " + "select a, b from t3");
    // Multiple views in WITH clause. All views used in a union.
    AnalyzesOk("with t1 as (select int_col x, bigint_col y from functional.alltypes), " + "t2 as (select 1 x , 10 y), t3 as (values(2 x , 20 y), (3, 30)), " + "t4 as (select 4 x, 40 y union all select 5, 50), " + "t5 as (select * from (values(6 x, 60 y)) as a) " + "select * from t1 union all select * from t2 union all select * from t3 " + "union all select * from t4 union all select * from t5");
    // Multiple views in WITH clause. All views used in a join.
    AnalyzesOk("with t1 as (select int_col x, bigint_col y from functional.alltypes), " + "t2 as (select 1 x , 10 y), t3 as (values(2 x , 20 y), (3, 30)), " + "t4 as (select 4 x, 40 y union all select 5, 50), " + "t5 as (select * from (values(6 x, 60 y)) as a) " + "select t1.y, t2.y, t3.y, t4.y, t5.y from t1, t2, t3, t4, t5 " + "where t1.y = t2.y and t2.y = t3.y and t3.y = t4.y and t4.y = t5.y");
    // Multiple views in WITH clause with column labels. All views used in a join.
    AnalyzesOk("with t1(c1, c2) as (select int_col x, bigint_col y " + "from functional.alltypes), " + "t2(c1, c2) as (select 1 x , 10 y), t3 as (values(2 x , 20 y), (3, 30)), " + "t4 as (select 4 x, 40 y union all select 5, 50), " + "t5 as (select * from (values(6 x, 60 y)) as a) " + "select t1.c2, t2.c2, t3.y, t4.y, t5.y from t1, t2, t3, t4, t5 " + "where t1.c2 = t2.c2 and t2.c2 = t3.y and t3.y = t4.y and t4.y = t5.y");
    // WITH clause in insert statement.
    AnalyzesOk("with t1 as (select * from functional.alltypestiny)" + "insert into functional.alltypes partition(year, month) select * from t1");
    AnalyzesOk("with t1(c1, c2) as (select * from functional.alltypestiny)" + "insert into functional.alltypes partition(year, month) select * from t1");
    // WITH clause in insert statement with a select statement that has a WITH
    // clause and an inline view (IMPALA-1100)
    AnalyzesOk("with test_ctas_1 as (select * from functional.alltypestiny) insert " + "into functional.alltypes partition (year, month) with with_1 as " + "(select t1.* from test_ctas_1 as t1 right join (select 1 as int_col " + "from functional.alltypestiny as t1) as t2 ON t2.int_col = t1.int_col) " + "select * from with_1 limit 10");
    // Insert with a select statement containing a WITH clause and an inline
    // view
    AnalyzesOk("insert into functional.alltypes partition (year, month) with " + "with_1 as (select t1.* from functional.alltypes as t1 right " + "join (select * from functional.alltypestiny as t1) t2 on t1.int_col = " + "t2.int_col) select * from with_1 limit 10");
    // WITH-clause views belong to different scopes.
    AnalyzesOk("with t1 as (select id from functional.alltypestiny) " + "insert into functional.alltypes partition(year, month) " + "with t1 as (select * from functional.alltypessmall) select * from t1");
    AnalyzesOk("with t(c1, c2) as (select * from functional.alltypes) " + "select a.c1, a.c2 from t a");
    // WITH-clause view used in inline view.
    AnalyzesOk("with t1 as (select 'a') select * from (select * from t1) as t2");
    AnalyzesOk("with t1 as (select 'a') " + "select * from (select * from (select * from t1) as t2) as t3");
    // WITH-clause inside inline view.
    AnalyzesOk("select * from (with t1 as (values(1 x, 10 y)) select * from t1) as t2");
    // Test case-insensitive matching of WITH-clause views to base table refs.
    AnalyzesOk("with T1 as (select int_col x, bigint_col y from functional.alltypes)," + "t2 as (select 1 x , 10 y), T3 as (values(2 x , 20 y), (3, 30)), " + "t4 as (select 4 x, 40 y union all select 5, 50), " + "T5 as (select * from (values(6 x, 60 y)) as a) " + "select * from t1 union all select * from T2 union all select * from t3 " + "union all select * from T4 union all select * from t5");
    // Multiple WITH clauses. One for the UnionStmt and one for each union operand.
    AnalyzesOk("with t1 as (values('a', 'b')) " + "(with t2 as (values('c', 'd')) select * from t2) union all" + "(with t3 as (values('e', 'f')) select * from t3) order by 1 limit 1");
    // Multiple WITH clauses. One before the insert and one inside the query statement.
    AnalyzesOk("with t1 as (select * from functional.alltypestiny) " + "insert into functional.alltypes partition(year, month) " + "with t2 as (select * from functional.alltypessmall) select * from t1");
    // Table aliases do not conflict because they are in different scopes.
    // Aliases are resolved from inner-most to the outer-most scope.
    AnalyzesOk("with t1 as (select 'a') " + "select t2.* from (with t1 as (select 'b') select * from t1) as t2");
    // Column labels do not conflict because they are in different scopes.
    AnalyzesOk("with t1(c1) as (select 'a') " + "select c1 from (with t1(c1) as (select 'b') select c1 from t1) as t2");
    // Table aliases do not conflict because t1 from the inline view is never used.
    AnalyzesOk("with t1 as (select 1), t2 as (select 2)" + "select * from functional.alltypes as t1");
    AnalyzesOk("with t1 as (select 1), t2 as (select 2) select * from t2 as t1");
    AnalyzesOk("with t1 as (select 1) select * from (select 2) as t1");
    // Fully-qualified table does not conflict with WITH-clause table.
    AnalyzesOk("with alltypes as (select * from functional.alltypes) " + "select * from functional.alltypes union all select * from alltypes");
    // Column labels can be used with table aliases.
    AnalyzesOk("with t(c1) as (select id from functional.alltypes) " + "select a.c1 from t a");
    // Use a custom analyzer to change the default db to functional.
    // Recursion is prevented because 'alltypes' in t1 refers to the table
    // functional.alltypes, and 'alltypes' in the final query refers to the
    // view 'alltypes'.
    AnalyzesOk("with t1 as (select int_col x, bigint_col y from alltypes), " + "alltypes as (select x a, y b from t1)" + "select a, b from alltypes", createAnalyzer("functional"));
    // Recursion is prevented because of scoping rules. The inner 'complex_view'
    // refers to a view in the catalog.
    AnalyzesOk("with t1 as (select abc x, xyz y from complex_view), " + "complex_view as (select x a, y b from t1)" + "select a, b from complex_view", createAnalyzer("functional"));
    // Nested WITH clauses. Scoping prevents recursion.
    AnalyzesOk("with t1 as (with t1 as (select int_col x, bigint_col y from alltypes) " + "select x, y from t1), " + "alltypes as (select x a, y b from t1) " + "select a, b from alltypes", createAnalyzer("functional"));
    // Nested WITH clause inside a subquery.
    AnalyzesOk("with t1 as " + "(select * from (with t2 as (select * from functional.alltypes) " + "select * from t2) t3) " + "select * from t1");
    // Nested WITH clause inside a union stmt.
    AnalyzesOk("with t1 as " + "(with t2 as (values('a', 'b')) select * from t2 union all select * from t2) " + "select * from t1");
    // Nested WITH clause inside a union stmt's operand.
    AnalyzesOk("with t1 as " + "(select 'x', 'y' union all (with t2 as (values('a', 'b')) select * from t2)) " + "select * from t1");
    // Single WITH clause. Multiple references to same view.
    AnalyzesOk("with t as (select 1 x)" + "select x from t union all select x from t");
    // Multiple references in same select statement require aliases.
    AnalyzesOk("with t as (select 'a' x)" + "select t1.x, t2.x, t.x from t as t1, t as t2, t " + "where t1.x = t2.x and t2.x = t.x");
    // Test column labels in WITH-clause view for non-SlotRef exprs.
    AnalyzesOk("with t as (select int_col + 2, !bool_col from functional.alltypes) " + "select `int_col + 2`, `NOT bool_col` from t");
    // Test analysis of WITH clause after subquery rewrite does not pollute
    // global state (IMPALA-1357).
    AnalyzesOk("select 1 from (with w as (select 1 from functional.alltypes " + "where exists (select 1 from functional.alltypes)) select 1 from w) tt");
    AnalyzesOk("create table test_with as select 1 from (with w as " + "(select 1 from functional.alltypes where exists " + "(select 1 from functional.alltypes)) select 1 from w) tt");
    AnalyzesOk("insert into functional.alltypesnopart (id) select 1 from " + "(with w as (select 1 from functional.alltypes where exists " + "(select 1 from functional.alltypes)) select 1 from w) tt");
    // Conflicting table aliases in WITH clause.
    AnalysisError("with t1 as (select 1), t1 as (select 2) select * from t1", "Duplicate table alias: 't1'");
    // Check that aliases from WITH-clause views conflict with other table aliases.
    AnalysisError("with t1 as (select 1 x), t2 as (select 2 y)" + "select * from functional.alltypes as t1 inner join t1", "Duplicate table alias: 't1'");
    AnalysisError("with t1 as (select 1), t2 as (select 2) " + "select * from t2 as t1 inner join t1", "Duplicate table alias: 't1'");
    AnalysisError("with t1 as (select 1) select * from (select 2) as t1 inner join t1", "Duplicate table alias: 't1'");
    // With clause column labels must be used intead of aliases.
    AnalysisError("with t1(c1) as (select id cnt from functional.alltypes) " + "select cnt from t1", "Could not resolve column/field reference: 'cnt'");
    // With clause column labels must not exceed the number of columns in the query.
    AnalysisError("with t(c1, c2) as (select id from functional.alltypes) " + "select * from t", "WITH-clause view 't' returns 1 columns, but 2 labels were specified. The " + "number of column labels must be smaller or equal to the number of returned " + "columns.");
    // Multiple references in same select statement require aliases.
    AnalysisError("with t1 as (select 'a' x) select * from t1 inner join t1", "Duplicate table alias: 't1'");
    // If one was given, we must use the explicit alias for column references.
    AnalysisError("with t1 as (select 'a' x) select t1.x from t1 as t2", "Could not resolve column/field reference: 't1.x'");
    // WITH-clause tables cannot be inserted into.
    AnalysisError("with t1 as (select 'a' x) insert into t1 values('b' x)", "Table does not exist: default.t1");
    // The inner alltypes_view gets resolved to the catalog view.
    AnalyzesOk("with alltypes_view as (select int_col x from alltypes_view) " + "select x from alltypes_view", createAnalyzer("functional"));
    // The inner 't' is resolved to a non-existent base table.
    AnalysisError("with t as (select int_col x, bigint_col y from t1) " + "select x, y from t", "Could not resolve table reference: 't1'");
    AnalysisError("with t as (select 1 as x, 2 as y union all select * from t) " + "select x, y from t", "Could not resolve table reference: 't'");
    AnalysisError("with t as (select a.* from (select * from t) as a) " + "select x, y from t", "Could not resolve table reference: 't'");
    // The inner 't1' in a nested WITH clause gets resolved to a non-existent base table.
    AnalysisError("with t1 as (with t2 as (select * from t1) select * from t2) " + "select * from t1 ", "Could not resolve table reference: 't1'");
    AnalysisError("with t1 as " + "(select * from (with t2 as (select * from t1) select * from t2) t3) " + "select * from t1", "Could not resolve table reference: 't1'");
    // The inner 't1' in the gets resolved to a non-existent base table.
    AnalysisError("with t1 as " + "(with t2 as (select * from t1) select * from t2 union all select * from t2)" + "select * from t1", "Could not resolve table reference: 't1'");
    AnalysisError("with t1 as " + "(select 'x', 'y' union all (with t2 as (select * from t1) select * from t2))" + "select * from t1", "Could not resolve table reference: 't1'");
    // The 't2' inside 't1's definition gets resolved to a non-existent base table.
    AnalysisError("with t1 as (select int_col x, bigint_col y from t2), " + "t2 as (select int_col x, bigint_col y from t1) select x, y from t1", "Could not resolve table reference: 't2'");
    // WITH clause with subqueries
    AnalyzesOk("with t as (select * from functional.alltypesagg where id in " + "(select id from functional.alltypes)) select int_col from t");
    AnalyzesOk("with t as (select * from functional.alltypes) select * from " + "functional.alltypesagg a where exists (select id from t where t.id = a.id)");
    AnalyzesOk("with t as (select * from functional.alltypes) select * from " + "functional.alltypesagg where 10 > (select count(*) from t) and " + "100 < (select max(int_col) from t)");
    AnalyzesOk("with t as (select * from functional.alltypes a where exists " + "(select * from functional.alltypesagg t where t.id = 1 and a.id = t.id) " + "and not exists (select * from functional.alltypesagg b where b.id = 1 " + "and b.int_col = a.int_col)) select * from t");
    // WITH clause with a collection table ref.
    AnalyzesOk("with w as (select t.id, a.item from functional.allcomplextypes t, " + "t.int_array_col a) select * from w");
    // Deeply nested WITH clauses (see IMPALA-1106)
    AnalyzesOk("with with_1 as (select 1 as int_col_1), with_2 as " + "(select 1 as int_col_1 from (with with_3 as (select 1 as int_col_1 from " + "with_1) select 1 as int_col_1 from with_3) as t1) select 1 as int_col_1 " + "from with_2");
    AnalyzesOk("with with_1 as (select 1 as int_col_1), with_2 as (select 1 as " + "int_col_1 from (with with_3 as (select 1 as int_col_1 from with_1) " + "select 1 as int_col_1 from with_3) as t1), with_4 as (select 1 as " + "int_col_1 from with_2) select 1 as int_col_1 from with_4");
    AnalyzesOk("with with_1 as (select 1 as int_col_1), with_2 as (with with_3 " + "as (select 1 as int_col_1 from (with with_4 as (select 1 as int_col_1 " + "from with_1) select 1 as int_col_1 from with_4) as t1) select 1 as " + "int_col_1 from with_3) select 1 as int_col_1 from with_2");
    // WITH clasue with a between predicate
    AnalyzesOk("with with_1 as (select int_col from functional.alltypestiny " + "where int_col between 0 and 10) select * from with_1");
    // WITH clause with a between predicate in the select list
    AnalyzesOk("with with_1 as (select int_col between 0 and 10 " + "from functional.alltypestiny) select * from with_1");
    // WITH clause with a between predicate in the select list that
    // uses casting
    AnalyzesOk("with with_1 as (select timestamp_col between " + "cast('2001-01-01' as timestamp) and " + "(cast('2001-01-01' as timestamp) + interval 10 days) " + "from functional.alltypestiny) select * from with_1");
    // WITH clause with a between predicate that uses explicit casting
    AnalyzesOk("with with_1 as (select * from functional.alltypestiny " + "where timestamp_col between cast('2001-01-01' as timestamp) and " + "(cast('2001-01-01' as timestamp) + interval 10 days)) " + "select * from with_1");
}

@Test
public void TestViews() throws AnalysisException {
    // Simple selects on our pre-defined views.
    AnalyzesOk("select * from functional.alltypes_view");
    AnalyzesOk("select x, y, z from functional.alltypes_view_sub");
    AnalyzesOk("select abc, xyz from functional.complex_view");
    // Test a view on a view.
    AnalyzesOk("select * from functional.view_view");
    // Aliases of views.
    AnalyzesOk("select t.x, t.y, t.z from functional.alltypes_view_sub t");
    // Views in a union.
    AnalyzesOk("select * from functional.alltypes_view_sub union all " + "select * from functional.alltypes_view_sub");
    // View in a subquery.
    AnalyzesOk("select t.* from (select * from functional.alltypes_view_sub) t");
    // View in a WITH-clause view.
    AnalyzesOk("with t as (select * from functional.complex_view) " + "select abc, xyz from t");
    // Complex query on a complex view with a join and an aggregate.
    AnalyzesOk("select sum(t1.abc), t2.xyz from functional.complex_view t1 " + "inner join functional.complex_view t2 on (t1.abc = t2.abc) " + "group by t2.xyz");
    // Cannot insert into a view.
    AnalysisError("insert into functional.alltypes_view partition(year, month) " + "select * from functional.alltypes", "Impala does not support inserting into views: functional.alltypes_view");
    // Cannot load into a view.
    AnalysisError("load data inpath '/test-warehouse/tpch.lineitem/lineitem.tbl' " + "into table functional.alltypes_view", "LOAD DATA only supported for HDFS tables: functional.alltypes_view");
    // Need to give view-references an explicit alias.
    AnalysisError("select * from functional.alltypes_view_sub " + "inner join functional.alltypes_view_sub", "Duplicate table alias: 'functional.alltypes_view_sub'");
    // Column names were redefined in view.
    AnalysisError("select int_col from functional.alltypes_view_sub", "Could not resolve column/field reference: 'int_col'");
}

@Test
public void TestLoadData() throws AnalysisException {
    for (String overwrite : Lists.newArrayList("", "overwrite")) {
        // Load specific data file.
        AnalyzesOk(String.format("load data inpath '%s' %s into table tpch.lineitem", "/test-warehouse/tpch.lineitem/lineitem.tbl", overwrite));
        // Load files from a data directory.
        AnalyzesOk(String.format("load data inpath '%s' %s into table tpch.lineitem", "/test-warehouse/tpch.lineitem/", overwrite));
        // Load files from a data directory into a partition.
        AnalyzesOk(String.format("load data inpath '%s' %s into table " + "functional.alltypes partition(year=2009, month=12)", "/test-warehouse/tpch.lineitem/", overwrite));
        // Source directory cannot contain subdirs.
        AnalysisError(String.format("load data inpath '%s' %s into table tpch.lineitem", "/test-warehouse/", overwrite), "INPATH location 'hdfs://localhost:20500/test-warehouse' cannot " + "contain subdirectories.");
        // Source directory cannot be empty.
        AnalysisError(String.format("load data inpath '%s' %s into table tpch.lineitem", "/test-warehouse/emptytable", overwrite), "INPATH location 'hdfs://localhost:20500/test-warehouse/emptytable' " + "contains no visible files.");
        // Cannot load a hidden files.
        AnalysisError(String.format("load data inpath '%s' %s into table tpch.lineitem", "/test-warehouse/alltypessmall/year=2009/month=1/.hidden", overwrite), "INPATH location 'hdfs://localhost:20500/test-warehouse/alltypessmall/" + "year=2009/month=1/.hidden' points to a hidden file.");
        AnalysisError(String.format("load data inpath '%s' %s into table tpch.lineitem", "/test-warehouse/alltypessmall/year=2009/month=1/_hidden", overwrite), "INPATH location 'hdfs://localhost:20500/test-warehouse/alltypessmall/" + "year=2009/month=1/_hidden' points to a hidden file.");
        // Source directory does not exist.
        AnalysisError(String.format("load data inpath '%s' %s into table tpch.lineitem", "/test-warehouse/does_not_exist", overwrite), "INPATH location 'hdfs://localhost:20500/test-warehouse/does_not_exist' " + "does not exist.");
        // Empty source directory string
        AnalysisError(String.format("load data inpath '%s' %s into table tpch.lineitem", "", overwrite), "URI path cannot be empty.");
        // Partition spec does not exist in table.
        AnalysisError(String.format("load data inpath '%s' %s into table " + "functional.alltypes partition(year=123, month=10)", "/test-warehouse/tpch.lineitem/", overwrite), "Partition spec does not exist: (year=123, month=10)");
        // Cannot load into non-HDFS tables.
        AnalysisError(String.format("load data inpath '%s' %s into table " + "functional_hbase.alltypessmall", "/test-warehouse/tpch.lineitem/", overwrite), "LOAD DATA only supported for HDFS tables: functional_hbase.alltypessmall");
        // Load into partitioned table without specifying a partition spec.
        AnalysisError(String.format("load data inpath '%s' %s into table " + "functional.alltypes", "/test-warehouse/tpch.lineitem/", overwrite), "Table is partitioned but no partition spec was specified: " + "functional.alltypes");
        // Database/table do not exist.
        AnalysisError(String.format("load data inpath '%s' %s into table " + "nodb.alltypes", "/test-warehouse/tpch.lineitem/", overwrite), "Database does not exist: nodb");
        AnalysisError(String.format("load data inpath '%s' %s into table " + "functional.notbl", "/test-warehouse/tpch.lineitem/", overwrite), "Table does not exist: functional.notbl");
        // Source must be HDFS.
        AnalysisError(String.format("load data inpath '%s' %s into table " + "tpch.lineitem", "file:///test-warehouse/test.out", overwrite), "INPATH location 'file:/test-warehouse/test.out' must point to an " + "HDFS filesystem");
        AnalysisError(String.format("load data inpath '%s' %s into table " + "tpch.lineitem", "s3n://bucket/test-warehouse/test.out", overwrite), "INPATH location 's3n://bucket/test-warehouse/test.out' must point to an " + "HDFS filesystem");
        // File type / table type mismatch.
        AnalyzesOk(String.format("load data inpath '%s' %s into table " + "tpch.lineitem", "/test-warehouse/alltypes_text_lzo/year=2009/month=4", overwrite));
        // When table type matches, analysis passes for partitioned and unpartitioned
        // tables.
        AnalyzesOk(String.format("load data inpath '%s' %s into table " + "functional_text_lzo.alltypes partition(year=2009, month=4)", "/test-warehouse/alltypes_text_lzo/year=2009/month=4", overwrite));
        AnalyzesOk(String.format("load data inpath '%s' %s into table " + "functional_text_lzo.jointbl", "/test-warehouse/alltypes_text_lzo/year=2009/month=4", overwrite));
        // Verify with a read-only table
        AnalysisError(String.format("load data inpath '%s' into table " + "functional_seq.alltypes partition(year=2009, month=3)", "/test-warehouse/alltypes_seq/year=2009/month=5", overwrite), "Unable to LOAD DATA into target table (functional_seq.alltypes) because " + "Impala does not have WRITE access to HDFS location: " + "hdfs://localhost:20500/test-warehouse/alltypes_seq/year=2009/month=3");
    }
}

@Test
public void TestInsert() throws AnalysisException {
    for (String qualifier : ImmutableList.of("INTO", "OVERWRITE")) {
        testInsertStatic(qualifier);
        testInsertDynamic(qualifier);
        testInsertUnpartitioned(qualifier);
        testInsertWithPermutation(qualifier);
    }
    // Test INSERT into a table that Impala does not have WRITE access to.
    AnalysisError("insert into functional_seq.alltypes partition(year, month)" + "select * from functional.alltypes", "Unable to INSERT into target table (functional_seq.alltypes) because Impala " + "does not have WRITE access to at least one HDFS path: " + "hdfs://localhost:20500/test-warehouse/alltypes_seq/year=2009/month=");
    // Insert with a correlated inline view.
    AnalyzesOk("insert into table functional.alltypessmall " + "partition (year, month)" + "select a.id, bool_col, tinyint_col, smallint_col, item, bigint_col, " + "float_col, double_col, date_string_col, string_col, timestamp_col, a.year, " + "b.month from functional.alltypes a, functional.allcomplextypes b, " + "(select item from b.int_array_col) v1 " + "where a.id = b.id");
    AnalysisError("insert into table functional.alltypessmall " + "partition (year, month)" + "select a.id, a.bool_col, a.tinyint_col, a.smallint_col, item, a.bigint_col, " + "a.float_col, a.double_col, a.date_string_col, a.string_col, a.timestamp_col, " + "a.year, b.month from functional.alltypes a, functional.allcomplextypes b, " + "(select item from b.int_array_col, functional.alltypestiny) v1 " + "where a.id = b.id", "Nested query is illegal because it contains a table reference " + "'b.int_array_col' correlated with an outer block as well as an " + "uncorrelated one 'functional.alltypestiny':\n" + "SELECT item FROM b.int_array_col, functional.alltypestiny");
    // Test plan hints for partitioned Hdfs tables.
    AnalyzesOk("insert into functional.alltypessmall " + "partition (year, month) [shuffle] select * from functional.alltypes");
    AnalyzesOk("insert into table functional.alltypessmall " + "partition (year, month) [noshuffle] select * from functional.alltypes");
    // Multiple non-conflicting hints and case insensitivity of hints.
    AnalyzesOk("insert into table functional.alltypessmall " + "partition (year, month) [shuffle, ShUfFlE] select * from functional.alltypes");
    // Unknown plan hint. Expect a warning but no error.
    AnalyzesOk("insert into functional.alltypessmall " + "partition (year, month) [badhint] select * from functional.alltypes", "INSERT hint not recognized: badhint");
    // Conflicting plan hints.
    AnalysisError("insert into table functional.alltypessmall " + "partition (year, month) [shuffle, noshuffle] select * from functional.alltypes", "Conflicting INSERT hint: noshuffle");
    // Plan hints require a partition clause.
    AnalysisError("insert into table functional.alltypesnopart [shuffle] " + "select * from functional.alltypesnopart", "INSERT hints are only supported for inserting into partitioned Hdfs tables.");
    // Plan hints do not make sense for inserting into HBase tables.
    AnalysisError("insert into table functional_hbase.alltypes [shuffle] " + "select * from functional_hbase.alltypes", "INSERT hints are only supported for inserting into partitioned Hdfs tables.");
}

