@Test
public void TestWithClause() throws AuthorizationException, AnalysisException {
    // With clause. No audit event should be recorded for the with-clause view.
    Set<TAccessEvent> accessEvents = AnalyzeAccessEvents("with t as (select * from functional.alltypesagg) select * from t");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional.alltypesagg", TCatalogObjectType.TABLE, "SELECT")));
    // With clause view referencing a catalog view.
    accessEvents = AnalyzeAccessEvents("with t as (select * from functional.alltypes_view) select * from t");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional.alltypes_view", TCatalogObjectType.VIEW, "SELECT"), new TAccessEvent("functional.alltypes", TCatalogObjectType.TABLE, "SELECT")));
    accessEvents = AnalyzeAccessEvents("with t as (select 1 + 2) select * from t");
    Assert.assertEquals(0, accessEvents.size());
    // Even though the with-clause view isn't selected an access event is generated.
    accessEvents = AnalyzeAccessEvents("with t as (select * from functional.alltypes) select 'abc'");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional.alltypes", TCatalogObjectType.TABLE, "SELECT")));
    accessEvents = AnalyzeAccessEvents("with t as (select * from functional.alltypes) " + "select * from functional_seq.alltypes");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional.alltypes", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_seq.alltypes", TCatalogObjectType.TABLE, "SELECT")));
}

