@Test
public void TestInsert() throws AuthorizationException, AnalysisException {
    AuthzOk("insert into functional_parquet.alltypes " + "partition(month,year) select * from functional_seq_snap.alltypes");
    // Insert + inline view (user has permissions).
    AuthzOk("insert into functional.alltypes partition(month,year) " + "select b.* from functional.alltypesagg a join (select * from " + "functional_seq_snap.alltypes) b on (a.int_col = b.int_col)");
    // User doesn't have INSERT permissions in the target table.
    AuthzError("insert into functional.alltypesagg select 1", "User '%s' does not have privileges to execute 'INSERT' on: " + "functional.alltypesagg");
    // User doesn't have INSERT permissions in the target view.
    // Inserting into a view is not allowed.
    AuthzError("insert into functional.alltypes_view select 1", "User '%s' does not have privileges to execute 'INSERT' on: " + "functional.alltypes_view");
    // User doesn't have SELECT permissions on source table.
    AuthzError("insert into functional.alltypes " + "select * from functional.alltypes", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes");
    // User doesn't have permissions on source table within inline view.
    AuthzError("insert into functional.alltypes " + "select * from functional.alltypesagg a join (select * from " + "functional_seq.alltypes) b on (a.int_col = b.int_col)", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional_seq.alltypes");
    // User doesn't have INSERT permissions on the target table but has sufficient SELECT
    // permissions on all the referenced columns of the source table
    AuthzError("insert into functional.alltypestiny partition (month, year) " + "select * from functional.alltypestiny", "User '%s' does not have " + "privileges to execute 'INSERT' on: functional.alltypestiny");
    // User has INSERT permissions on target table but insufficient column-level
    // permissions on the source table
    AuthzError("insert into functional.alltypes partition (month, year) " + "select * from functional.alltypessmall", "User '%s' does not have " + "privileges to execute 'SELECT' on: functional.alltypessmall");
    // User has INSERT permissions on the target table and SELECT permissions on
    // all the columns of the source table
    AuthzOk("insert into functional.alltypes partition (month, year) " + "select * from functional.alltypestiny where id < 100");
    // Same as above with a column permutation
    AuthzOk("insert into table functional.alltypes" + "(id, bool_col, string_col, smallint_col, int_col, bigint_col, " + "float_col, double_col, date_string_col, tinyint_col, timestamp_col) " + "partition (month, year) select id, bool_col, string_col, smallint_col, " + "int_col, bigint_col, float_col, double_col, date_string_col, tinyint_col, " + "timestamp_col, month, year from functional.alltypestiny");
}

@Test
public void TestWithClause() throws AuthorizationException, AnalysisException {
    // User has SELECT privileges on table in WITH-clause view.
    AuthzOk("with t as (select * from functional.alltypesagg) select * from t");
    // User doesn't have SELECT privileges on table in WITH-clause view.
    AuthzError("with t as (select * from functional.alltypes) select * from t", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes");
    // User has SELECT privileges on view in WITH-clause view.
    AuthzOk("with t as (select * from functional.complex_view) select * from t");
    // User has SELECT privileges on table in WITH-clause view in INSERT.
    AuthzOk("with t as (select * from functional_seq_snap.alltypes) " + "insert into functional_parquet.alltypes partition(month,year) select * from t");
    // User doesn't have SELECT privileges on table in WITH-clause view in INSERT.
    AuthzError("with t as (select * from functional_parquet.alltypes) " + "insert into functional_parquet.alltypes partition(month,year) select * from t", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional_parquet.alltypes");
    // User doesn't have SELECT privileges on view in WITH-clause view in INSERT.
    AuthzError("with t as (select * from functional.alltypes_view) " + "insert into functional_parquet.alltypes partition(month,year) select * from t", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes_view");
    // User has SELECT privileges on columns referenced in the WITH-clause view.
    AuthzOk("with t as (select id, int_col from functional.alltypessmall) " + "select * from t");
    // User does not have SELECT privileges on 'month'
    AuthzError("with t as (select id, int_col from functional.alltypessmall " + "where month = 10) select count(*) from t", "User '%s' does not have " + "privileges to execute 'SELECT' on: functional.alltypessmall");
}

@Test
public void TestExplain() throws AuthorizationException, AnalysisException {
    AuthzOk("explain select * from functional.alltypesagg");
    AuthzOk("explain insert into functional_parquet.alltypes " + "partition(month,year) select * from functional_seq_snap.alltypes");
    // Select without permissions.
    AuthzError("explain select * from functional.alltypes", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes");
    // Insert with no select permissions on source table.
    AuthzError("explain insert into functional_parquet.alltypes " + "partition(month,year) select * from functional.alltypes", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes");
    // Insert, user doesn't have permissions on source table.
    AuthzError("explain insert into functional.alltypes " + "select * from functional.alltypes", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes");
    // Test explain on views. User has permissions on all the underlying tables.
    AuthzOk("explain select * from functional_seq_snap.alltypes_view");
    AuthzOk("explain insert into functional_parquet.alltypes " + "partition(month,year) select * from functional_seq_snap.alltypes_view");
    // Select on view without permissions on view.
    AuthzError("explain select * from functional.alltypes_view", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes_view");
    // Insert into view without permissions on view.
    AuthzError("explain insert into functional.alltypes_view " + "select * from functional_seq_snap.alltypes ", "User '%s' does not have privileges to execute 'INSERT' on: " + "functional.alltypes_view");
    // User has permission on view, but not on underlying tables.
    AuthzError("explain select * from functional.complex_view", "User '%s' does not have privileges to EXPLAIN this statement.");
    // User has permission on view in WITH clause, but not on underlying tables.
    AuthzError("explain with t as (select * from functional.complex_view) " + "select * from t", "User '%s' does not have privileges to EXPLAIN this statement.");
    // User has permission on view in WITH clause, but not on underlying tables.
    AuthzError("explain with t as (select * from functional.complex_view) " + "select * from t", "User '%s' does not have privileges to EXPLAIN this statement.");
    // User has permission on view and on view inside view,
    // but not on tables in view inside view.
    AuthzError("explain select * from functional.view_view", "User '%s' does not have privileges to EXPLAIN this statement.");
    // User doesn't have permission on tables in view inside view.
    AuthzError("explain insert into functional_seq_snap.alltypes " + "partition(month,year) select * from functional.view_view", "User '%s' does not have privileges to EXPLAIN this statement.");
    // User has SELECT privileges on the view, but does not have privileges
    // to select join table. Should get standard auth message back.
    AuthzError("explain select a.id from functional.view_view a " + "join functional.alltypes b ON (a.id = b.id)", "User '%s' does not have privileges to execute 'SELECT' on: " + "functional.alltypes");
    // User has privileges on tables inside the first view, but not the second
    // view. Should get masked auth error back.
    AuthzError("explain select a.id from functional.view_view a " + "join functional.complex_view b ON (a.id = b.id)", "User '%s' does not have privileges to EXPLAIN this statement.");
    // User has SELECT privileges on all referenced columns
    AuthzOk("explain select * from functional.alltypestiny");
    // User doesn't have SELECT privileges on all referenced columns
    AuthzError("explain select * from functional.alltypessmall", "User '%s' " + "does not have privileges to execute 'SELECT' on: functional.alltypessmall");
}

