@Test
public void TestCreateDatabase() throws ImpalaException {
    // Database already exists (no permissions).
    AuthzError("create database functional", "User '%s' does not have privileges to execute 'CREATE' on: functional");
    // Non existent db (no permissions).
    AuthzError("create database nodb", "User '%s' does not have privileges to execute 'CREATE' on: nodb");
    // Non existent db (no permissions).
    AuthzError("create database if not exists _impala_builtins", "Cannot modify system database.");
    // TODO: Add test support for dynamically changing privileges for
    // file-based policy.
    if (authzConfig_.isFileBasedPolicy())
        return;
    SentryPolicyService sentryService = new SentryPolicyService(authzConfig_.getSentryConfig());
    try {
        sentryService.grantRoleToGroup(USER, "admin", USER.getName());
        ((ImpaladTestCatalog) catalog_).reset();
        // User has permissions to create database.
        AuthzOk("create database newdb");
        // Create database with location specified explicitly (user has permission).
        // Since create database requires server-level privileges there should never
        // be a case where the user has privileges to create a database does not have
        // privileges on the URI.
        AuthzOk("create database newdb location " + "'hdfs://localhost:20500/test-warehouse/new_table'");
    } finally {
        sentryService.revokeRoleFromGroup(USER, "admin", USER.getName());
        ((ImpaladTestCatalog) catalog_).reset();
    }
}

@Test
public void TestDropDatabase() throws AnalysisException, AuthorizationException {
    // User has permissions.
    AuthzOk("drop database tpch");
    AuthzOk("drop database tpch cascade");
    AuthzOk("drop database tpch restrict");
    // User has permissions, database does not exists and IF EXISTS specified.
    AuthzOk("drop database if exists newdb");
    AuthzOk("drop database if exists newdb cascade");
    AuthzOk("drop database if exists newdb restrict");
    // User has permission, database does not exists, IF EXISTS not specified.
    try {
        AuthzOk("drop database newdb");
        fail("Expected analysis error");
    } catch (AnalysisException e) {
        Assert.assertEquals(e.getMessage(), "Database does not exist: newdb");
    }
    try {
        AuthzOk("drop database newdb cascade");
        fail("Expected analysis error");
    } catch (AnalysisException e) {
        Assert.assertEquals(e.getMessage(), "Database does not exist: newdb");
    }
    try {
        AuthzOk("drop database newdb restrict");
        fail("Expected analysis error");
    } catch (AnalysisException e) {
        Assert.assertEquals(e.getMessage(), "Database does not exist: newdb");
    }
    // Database exists, user doesn't have permission to drop.
    AuthzError("drop database functional", "User '%s' does not have privileges to execute 'DROP' on: functional");
    AuthzError("drop database if exists functional", "User '%s' does not have privileges to execute 'DROP' on: functional");
    AuthzError("drop database if exists functional cascade", "User '%s' does not have privileges to execute 'DROP' on: functional");
    AuthzError("drop database if exists functional restrict", "User '%s' does not have privileges to execute 'DROP' on: functional");
    // Database does not exist, user doesn't have permission to drop.
    AuthzError("drop database nodb", "User '%s' does not have privileges to execute 'DROP' on: nodb");
    AuthzError("drop database if exists nodb", "User '%s' does not have privileges to execute 'DROP' on: nodb");
    AuthzError("drop database if exists nodb cascade", "User '%s' does not have privileges to execute 'DROP' on: nodb");
    AuthzError("drop database if exists nodb restrict", "User '%s' does not have privileges to execute 'DROP' on: nodb");
