    TMetadataOpRequest req = new TMetadataOpRequest();
    req.setSession(createSessionState("default", USER));
    req.opcode = TMetadataOpcode.GET_TABLES;
    req.get_tables_req = new TGetTablesReq();
    req.get_tables_req.setSchemaName("functional");
    // Get all tables
    req.get_tables_req.setTableName("%");
    TResultSet resp = fe_.execHiveServer2MetadataOp(req);
    assertEquals(7, resp.rows.size());
    assertEquals("allcomplextypes", resp.rows.get(0).colVals.get(2).string_val.toLowerCase());
    assertEquals("alltypes", resp.rows.get(1).colVals.get(2).string_val.toLowerCase());
    assertEquals("alltypesagg", resp.rows.get(2).colVals.get(2).string_val.toLowerCase());
    assertEquals("alltypessmall", resp.rows.get(3).colVals.get(2).string_val.toLowerCase());
    assertEquals("alltypestiny", resp.rows.get(4).colVals.get(2).string_val.toLowerCase());
    assertEquals("complex_view", resp.rows.get(5).colVals.get(2).string_val.toLowerCase());
    assertEquals("view_view", resp.rows.get(6).colVals.get(2).string_val.toLowerCase());
    // Get all tables of tpcds
    req.get_tables_req.setSchemaName("tpcds");
    req.get_tables_req.setTableName("%");
    resp = fe_.execHiveServer2MetadataOp(req);
    assertEquals(11, resp.rows.size());
}

@Test
public void TestHs2GetSchema() throws ImpalaException {
    TMetadataOpRequest req = new TMetadataOpRequest();
    req.setSession(createSessionState("default", USER));
