@Test
public void TestHs2GetColumns() throws ImpalaException {
    // It should return one column: alltypes.string_col.
    TMetadataOpRequest req = new TMetadataOpRequest();
    req.opcode = TMetadataOpcode.GET_COLUMNS;
    req.setSession(createSessionState("default", USER));
    req.get_columns_req = new TGetColumnsReq();
    req.get_columns_req.setSchemaName("functional");
    req.get_columns_req.setTableName("alltypes");
    req.get_columns_req.setColumnName("stri%");
    TResultSet resp = fe_.execHiveServer2MetadataOp(req);
    assertEquals(1, resp.rows.size());
    // User does not have permission to access the table, no results should be returned.
    req.get_columns_req.setTableName("alltypesnopart");
    resp = fe_.execHiveServer2MetadataOp(req);
    assertEquals(0, resp.rows.size());
    // User does not have permission to access db or table, no results should be
    // returned.
    req.get_columns_req.setSchemaName("functional_seq_gzip");
    req.get_columns_req.setTableName("alltypes");
    resp = fe_.execHiveServer2MetadataOp(req);
    assertEquals(0, resp.rows.size());
    // User has SELECT privileges on all table columns but no table-level privileges.
    req.get_columns_req.setSchemaName("functional");
    req.get_columns_req.setTableName("alltypestiny");
    req.get_columns_req.setColumnName("%");
    resp = fe_.execHiveServer2MetadataOp(req);
    assertEquals(13, resp.rows.size());
    // User has SELECT privileges on some columns but no table-level privileges.
    req.get_columns_req.setSchemaName("functional");
    req.get_columns_req.setTableName("alltypessmall");
    req.get_columns_req.setColumnName("%");
    resp = fe_.execHiveServer2MetadataOp(req);
    String[] expectedColumnNames = { "id", "int_col", "year" };
    assertEquals(expectedColumnNames.length, resp.rows.size());
    for (int i = 0; i < resp.rows.size(); ++i) {
        assertEquals(expectedColumnNames[i], resp.rows.get(i).colVals.get(3).string_val.toLowerCase());
    }
}

@Test
public void TestShortUsernameUsed() throws AnalysisException, AuthorizationException {
    // Different long variations of the same username.
    List<User> users = Lists.newArrayList(new User(USER.getName() + "/abc.host.com"), new User(USER.getName() + "/abc.host.com@REAL.COM"), new User(USER.getName() + "@REAL.COM"));
    for (User user : users) {
        AnalysisContext context = new AnalysisContext(catalog_, TestUtils.createQueryContext(Catalog.DEFAULT_DB, user.getName()), authzConfig_);
        // Can select from table that user has privileges on.
        AuthzOk(context, "select * from functional.alltypesagg");
        // Unqualified table name.
        AuthzError(context, "select * from alltypes", "User '%s' does not have privileges to execute 'SELECT' on: default.alltypes", user);
    }
    // If the first character is '/' or '@', the short username should be the same as
    // the full username.
    assertEquals("/" + USER.getName(), new User("/" + USER.getName()).getShortName());
    assertEquals("@" + USER.getName(), new User("@" + USER.getName()).getShortName());
}

@Test
public void TestFunction() throws ImpalaException {
    // First try with the less privileged user.
    User currentUser = USER;
    AnalysisContext context = new AnalysisContext(catalog_, TestUtils.createQueryContext(Catalog.DEFAULT_DB, currentUser.getName()), authzConfig_);
    AuthzError(context, "show functions", "User '%s' does not have privileges to access: default", currentUser);
    AuthzOk(context, "show functions in tpch");
    AuthzError(context, "create function f() returns int location " + "'/test-warehouse/libTestUdfs.so' symbol='NoArgs'", "User '%s' does not have privileges to CREATE/DROP functions.", currentUser);
    AuthzError(context, "create function tpch.f() returns int location " + "'/test-warehouse/libTestUdfs.so' symbol='NoArgs'", "User '%s' does not have privileges to CREATE/DROP functions.", currentUser);
    AuthzError(context, "create function notdb.f() returns int location " + "'/test-warehouse/libTestUdfs.so' symbol='NoArgs'", "User '%s' does not have privileges to CREATE/DROP functions.", currentUser);
    AuthzError(context, "drop function if exists f()", "User '%s' does not have privileges to CREATE/DROP functions.", currentUser);
    AuthzError(context, "drop function notdb.f()", "User '%s' does not have privileges to CREATE/DROP functions.", currentUser);
    // TODO: Add test support for dynamically changing privileges for
    // file-based policy.
    if (authzConfig_.isFileBasedPolicy())
        return;
    // Admin should be able to do everything
    SentryPolicyService sentryService = new SentryPolicyService(authzConfig_.getSentryConfig());
    try {
        sentryService.grantRoleToGroup(USER, "admin", USER.getName());
        ((ImpaladTestCatalog) catalog_).reset();
        AuthzOk("show functions");
        AuthzOk("show functions in tpch");
        AuthzOk("create function f() returns int location " + "'/test-warehouse/libTestUdfs.so' symbol='NoArgs'");
        AuthzOk("create function tpch.f() returns int location " + "'/test-warehouse/libTestUdfs.so' symbol='NoArgs'");
        AuthzOk("drop function if exists f()");
        // Can't add function to system db
        AuthzError("create function _impala_builtins.f() returns int location " + "'/test-warehouse/libTestUdfs.so' symbol='NoArgs'", "Cannot modify system database.");
        AuthzError("drop function if exists pi()", "Cannot modify system database.");
        // Add default.f(), tpch.f()
        catalog_.addFunction(new ScalarFunction(new FunctionName("default", "f"), new ArrayList<Type>(), Type.INT, null, null, null, null));
        catalog_.addFunction(new ScalarFunction(new FunctionName("tpch", "f"), new ArrayList<Type>(), Type.INT, null, null, null, null));
        AuthzOk("drop function tpch.f()");
    } finally {
        sentryService.revokeRoleFromGroup(USER, "admin", USER.getName());
        ((ImpaladTestCatalog) catalog_).reset();
        AuthzError(context, "create function tpch.f() returns int location " + "'/test-warehouse/libTestUdfs.so' symbol='NoArgs'", "User '%s' does not have privileges to CREATE/DROP functions.", currentUser);
        // Couldn't create tpch.f() but can run it.
        AuthzOk("select tpch.f()");
        //Other tests don't expect tpch to contain functions
        //Specifically, if these functions are not cleaned up, TestDropDatabase() will fail
        catalog_.removeFunction(new ScalarFunction(new FunctionName("default", "f"), new ArrayList<Type>(), Type.INT, null, null, null, null));
        catalog_.removeFunction(new ScalarFunction(new FunctionName("tpch", "f"), new ArrayList<Type>(), Type.INT, null, null, null, null));
    }
}

