@Test
public void TestConfigValidation() throws InternalException {
    String sentryConfig = authzConfig_.getSentryConfig().getConfigFile();
    // Valid configs pass validation.
    AuthorizationConfig config = AuthorizationConfig.createHadoopGroupAuthConfig("server1", AUTHZ_POLICY_FILE, sentryConfig);
    config.validateConfig();
    Assert.assertTrue(config.isEnabled());
    Assert.assertTrue(config.isFileBasedPolicy());
    config = AuthorizationConfig.createHadoopGroupAuthConfig("server1", null, sentryConfig);
    config.validateConfig();
    Assert.assertTrue(config.isEnabled());
    Assert.assertTrue(!config.isFileBasedPolicy());
    // Invalid configs
    // No sentry configuration file.
    config = AuthorizationConfig.createHadoopGroupAuthConfig("server1", AUTHZ_POLICY_FILE, null);
    Assert.assertTrue(config.isEnabled());
    try {
        config.validateConfig();
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "A valid path to a sentry-site.xml config " + "file must be set using --sentry_config to enable authorization.");
    }
    // Empty / null server name.
    config = AuthorizationConfig.createHadoopGroupAuthConfig("", AUTHZ_POLICY_FILE, sentryConfig);
    Assert.assertTrue(config.isEnabled());
    try {
        config.validateConfig();
        fail("Expected configuration to fail.");
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), "Authorization is enabled but the server name is null or empty. Set the " + "server name using the impalad --server_name flag.");
    }
    config = AuthorizationConfig.createHadoopGroupAuthConfig(null, AUTHZ_POLICY_FILE, sentryConfig);
    Assert.assertTrue(config.isEnabled());
    try {
        config.validateConfig();
        fail("Expected configuration to fail.");
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), "Authorization is enabled but the server name is null or empty. Set the " + "server name using the impalad --server_name flag.");
    }
    // Sentry config file does not exist.
    config = AuthorizationConfig.createHadoopGroupAuthConfig("server1", "", "/path/does/not/exist.xml");
    Assert.assertTrue(config.isEnabled());
    try {
        config.validateConfig();
        fail("Expected configuration to fail.");
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "Sentry configuration file does not exist: /path/does/not/exist.xml");
    }
    // Invalid ResourcePolicyProvider class name.
    config = new AuthorizationConfig("server1", AUTHZ_POLICY_FILE, "", "ClassDoesNotExist");
    Assert.assertTrue(config.isEnabled());
    try {
        config.validateConfig();
        fail("Expected configuration to fail.");
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), "The authorization policy provider class 'ClassDoesNotExist' was not found.");
    }
    // Valid class name, but class is not derived from ResourcePolicyProvider
    config = new AuthorizationConfig("server1", AUTHZ_POLICY_FILE, "", this.getClass().getName());
    Assert.assertTrue(config.isEnabled());
    try {
        config.validateConfig();
        fail("Expected configuration to fail.");
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), String.format("The authorization policy " + "provider class '%s' must be a subclass of '%s'.", this.getClass().getName(), ResourceAuthorizationProvider.class.getName()));
    }
    // Config validations skipped if authorization disabled
    config = new AuthorizationConfig("", "", "", "");
    Assert.assertFalse(config.isEnabled());
    config = new AuthorizationConfig(null, "", "", null);
    Assert.assertFalse(config.isEnabled());
    config = new AuthorizationConfig("", null, "", "");
    Assert.assertFalse(config.isEnabled());
    config = new AuthorizationConfig(null, null, null, null);
    Assert.assertFalse(config.isEnabled());
}

@Test
public void TestLocalGroupPolicyProvider() throws AnalysisException, AuthorizationException {
    if (!authzConfig_.isFileBasedPolicy())
        return;
    // Use an authorization configuration that uses the
    // LocalGroupResourceAuthorizationProvider.
    AuthorizationConfig authzConfig = new AuthorizationConfig("server1", AUTHZ_POLICY_FILE, "", LocalGroupResourceAuthorizationProvider.class.getName());
    ImpaladCatalog catalog = new ImpaladTestCatalog(authzConfig);
    // Create an analysis context + FE with the test user (as defined in the policy file)
    User user = new User("test_user");
    AnalysisContext context = new AnalysisContext(catalog, TestUtils.createQueryContext(Catalog.DEFAULT_DB, user.getName()), authzConfig);
    Frontend fe = new Frontend(authzConfig, catalog);
    // Can select from table that user has privileges on.
    AuthzOk(fe, context, "select * from functional.alltypesagg");
    // Does not have privileges to execute a query
    AuthzError(fe, context, "select * from functional.alltypes", "User '%s' does not have privileges to execute 'SELECT' on: functional.alltypes", user);
    // Verify with the admin user
    user = new User("admin_user");
    context = new AnalysisContext(catalog, TestUtils.createQueryContext(Catalog.DEFAULT_DB, user.getName()), authzConfig);
    fe = new Frontend(authzConfig, catalog);
    // Admin user should have privileges to do anything
    AuthzOk(fe, context, "select * from functional.alltypesagg");
    AuthzOk(fe, context, "select * from functional.alltypes");
    AuthzOk(fe, context, "invalidate metadata");
}

// Test creation of LiteralExprs from Strings, e.g., for partitioning keys.
@Test
public void TestLiteralExpr() {
    testLiteralExprPositive("false", Type.BOOLEAN);
    testLiteralExprPositive("1", Type.TINYINT);
    testLiteralExprPositive("1", Type.SMALLINT);
    testLiteralExprPositive("1", Type.INT);
    testLiteralExprPositive("1", Type.BIGINT);
    testLiteralExprPositive("1.0", Type.FLOAT);
    testLiteralExprPositive("1.0", Type.DOUBLE);
    testLiteralExprPositive("ABC", Type.STRING);
    testLiteralExprPositive("1.1", ScalarType.createDecimalType(2, 1));
    // INVALID_TYPE should always fail
    testLiteralExprNegative("ABC", Type.INVALID);
    // Invalid casts
    testLiteralExprNegative("ABC", Type.BOOLEAN);
    testLiteralExprNegative("ABC", Type.TINYINT);
    testLiteralExprNegative("ABC", Type.SMALLINT);
    testLiteralExprNegative("ABC", Type.INT);
    testLiteralExprNegative("ABC", Type.BIGINT);
    testLiteralExprNegative("ABC", Type.FLOAT);
    testLiteralExprNegative("ABC", Type.DOUBLE);
    testLiteralExprNegative("ABC", Type.TIMESTAMP);
    testLiteralExprNegative("ABC", ScalarType.createDecimalType());
    // Date types not implemented
    testLiteralExprNegative("2010-01-01", Type.DATE);
    testLiteralExprNegative("2010-01-01", Type.DATETIME);
    testLiteralExprNegative("2010-01-01", Type.TIMESTAMP);
}

