@Test
public void TestUdf() throws CatalogException {
    List<String> fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 0);
    ArrayList<Type> args1 = Lists.newArrayList();
    ArrayList<Type> args2 = Lists.<Type>newArrayList(Type.INT);
    ArrayList<Type> args3 = Lists.<Type>newArrayList(Type.TINYINT);
    catalog_.removeFunction(new Function(new FunctionName("default", "Foo"), args1, Type.INVALID, false));
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 0);
    ScalarFunction udf1 = new ScalarFunction(new FunctionName("default", "Foo"), args1, Type.INVALID, new HdfsUri("/Foo"), "Foo.class", null, null);
    catalog_.addFunction(udf1);
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 1);
    assertTrue(fnNames.contains("foo()"));
    // Same function name, overloaded arguments
    ScalarFunction udf2 = new ScalarFunction(new FunctionName("default", "Foo"), args2, Type.INVALID, new HdfsUri("/Foo"), "Foo.class", null, null);
    catalog_.addFunction(udf2);
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 2);
    assertTrue(fnNames.contains("foo()"));
    assertTrue(fnNames.contains("foo(INT)"));
    // Add a function with a new name
    ScalarFunction udf3 = new ScalarFunction(new FunctionName("default", "Bar"), args2, Type.INVALID, new HdfsUri("/Foo"), "Foo.class", null, null);
    catalog_.addFunction(udf3);
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 3);
    assertTrue(fnNames.contains("foo()"));
    assertTrue(fnNames.contains("foo(INT)"));
    assertTrue(fnNames.contains("bar(INT)"));
    // Drop Foo()
    catalog_.removeFunction(new Function(new FunctionName("default", "Foo"), args1, Type.INVALID, false));
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 2);
    assertTrue(fnNames.contains("foo(INT)"));
    assertTrue(fnNames.contains("bar(INT)"));
    // Drop it again, no-op
    catalog_.removeFunction(new Function(new FunctionName("default", "Foo"), args1, Type.INVALID, false));
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 2);
    assertTrue(fnNames.contains("foo(INT)"));
    assertTrue(fnNames.contains("bar(INT)"));
    // Drop bar(), no-op
    catalog_.removeFunction(new Function(new FunctionName("default", "Bar"), args1, Type.INVALID, false));
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 2);
    assertTrue(fnNames.contains("foo(INT)"));
    assertTrue(fnNames.contains("bar(INT)"));
    // Drop bar(tinyint), no-op
    catalog_.removeFunction(new Function(new FunctionName("default", "Bar"), args3, Type.INVALID, false));
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 2);
    assertTrue(fnNames.contains("foo(INT)"));
    assertTrue(fnNames.contains("bar(INT)"));
    // Drop bar(int)
    catalog_.removeFunction(new Function(new FunctionName("default", "Bar"), args2, Type.INVALID, false));
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 1);
    assertTrue(fnNames.contains("foo(INT)"));
    // Drop foo(int)
    catalog_.removeFunction(new Function(new FunctionName("default", "foo"), args2, Type.INVALID, false));
    fnNames = getFunctionSignatures("default");
    assertEquals(fnNames.size(), 0);
}

@Test
public void testCompare() {
    List<List<LiteralExpr>> allLists = Lists.newArrayList();
    allLists.add(valuesNull_);
    allLists.add(valuesDecimal_);
    allLists.add(valuesDecimal1_);
    allLists.add(valuesDecimal2_);
    allLists.add(valuesMixed_);
    allLists.add(valuesMixed1_);
    allLists.add(valuesMixed2_);
    for (List<LiteralExpr> l1 : allLists) {
        verifyReflexive(l1);
        for (List<LiteralExpr> l2 : allLists) {
            verifySymmetric(l1, l2);
            for (List<LiteralExpr> l3 : allLists) {
                verifyTransitive(l1, l2, l3);
            }
        }
    }
    List<LiteralExpr> valuesTest = Lists.newArrayList();
    valuesTest.add(new NumericLiteral(BigDecimal.valueOf(3)));
    verifyAntiSymmetric(valuesDecimal1_, valuesTest, valuesNull_);
    valuesTest.add(NullLiteral.create(Type.BIGINT));
    verifyAntiSymmetric(valuesMixed_, valuesTest, valuesDecimal_);
}

