/**
 * Tests that Impala is able to create an HdfsStorageDescriptor using all
 * combinations of Parquet SerDe class name + input/output format class name.
 */
@Test
public void testParquetFileFormat() throws DatabaseNotFoundException, InvalidStorageDescriptorException {
    String[] parquetSerDe = new String[] { "org.apache.hadoop.hive.ql.io.parquet.serde.ParquetHiveSerDe", "parquet.hive.serde.ParquetHiveSerDe" };
    String[] inputFormats = new String[] { "com.cloudera.impala.hive.serde.ParquetInputFormat", "parquet.hive.DeprecatedParquetInputFormat", "parquet.hive.MapredParquetInputFormat", "org.apache.hadoop.hive.ql.io.parquet.MapredParquetInputFormat" };
    String[] outputFormats = new String[] { "com.cloudera.impala.hive.serde.ParquetOutputFormat", "parquet.hive.DeprecatedParquetOutputFormat", "parquet.hive.MapredParquetOutputFormat", "org.apache.hadoop.hive.ql.io.parquet.MapredParquetOutputFormat" };
    for (String serDe : parquetSerDe) {
        SerDeInfo serDeInfo = new SerDeInfo();
        serDeInfo.setSerializationLib(serDe);
        serDeInfo.setParameters(new HashMap<String, String>());
        for (String inputFormat : inputFormats) {
            for (String outputFormat : outputFormats) {
                StorageDescriptor sd = new StorageDescriptor();
                sd.setSerdeInfo(serDeInfo);
                sd.setInputFormat(inputFormat);
                sd.setOutputFormat(outputFormat);
                assertNotNull(HdfsStorageDescriptor.fromStorageDescriptor("fakeTblName", sd));
            }
        }
    }
}

/**
 * Verifies Impala is able to properly parse delimiters in supported formats.
 * See HdfsStorageDescriptor.parseDelim() for details.
 */
@Test
public void testDelimiters() throws InvalidStorageDescriptorException {
    StorageDescriptor sd = HiveStorageDescriptorFactory.createSd(THdfsFileFormat.TEXT, RowFormat.DEFAULT_ROW_FORMAT);
    sd.setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "-2");
    assertNotNull(HdfsStorageDescriptor.fromStorageDescriptor("fakeTbl", sd));
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "-128");
    assertNotNull(HdfsStorageDescriptor.fromStorageDescriptor("fakeTbl", sd));
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "127");
    assertNotNull(HdfsStorageDescriptor.fromStorageDescriptor("fakeTbl", sd));
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.LINE_DELIM, "\001");
    assertNotNull(HdfsStorageDescriptor.fromStorageDescriptor("fakeTbl", sd));
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "|");
    assertNotNull(HdfsStorageDescriptor.fromStorageDescriptor("fakeTbl", sd));
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "\t");
    assertNotNull(HdfsStorageDescriptor.fromStorageDescriptor("fakeTbl", sd));
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "ab");
    try {
        HdfsStorageDescriptor.fromStorageDescriptor("fake", sd);
        fail();
    } catch (HdfsStorageDescriptor.InvalidStorageDescriptorException e) {
        assertEquals("Invalid delimiter: 'ab'. Delimiter must be specified as a " + "single character or as a decimal value in the range [-128:127]", e.getMessage());
    }
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "128");
    try {
        HdfsStorageDescriptor.fromStorageDescriptor("fake", sd);
        fail();
    } catch (HdfsStorageDescriptor.InvalidStorageDescriptorException e) {
        assertEquals("Invalid delimiter: '128'. Delimiter must be specified as a " + "single character or as a decimal value in the range [-128:127]", e.getMessage());
    }
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.FIELD_DELIM, "\128");
    try {
        HdfsStorageDescriptor.fromStorageDescriptor("fake", sd);
        fail();
    } catch (HdfsStorageDescriptor.InvalidStorageDescriptorException e) {
        assertEquals("Invalid delimiter: '\128'. Delimiter must be specified as a " + "single character or as a decimal value in the range [-128:127]", e.getMessage());
    }
    sd.getSerdeInfo().setParameters(new HashMap<String, String>());
    sd.getSerdeInfo().putToParameters(serdeConstants.LINE_DELIM, "-129");
    try {
        HdfsStorageDescriptor.fromStorageDescriptor("fake", sd);
        fail();
    } catch (HdfsStorageDescriptor.InvalidStorageDescriptorException e) {
        assertEquals("Invalid delimiter: '-129'. Delimiter must be specified as a " + "single character or as a decimal value in the range [-128:127]", e.getMessage());
    }
}

