@Test
public void TestGetFunctions() throws ImpalaException {
    // "sub%" should return functions subdate, substr and substring.
    TMetadataOpRequest req = new TMetadataOpRequest();
    req.opcode = TMetadataOpcode.GET_FUNCTIONS;
    req.get_functions_req = new TGetFunctionsReq();
    req.get_functions_req.setFunctionName("sub%");
    TResultSet resp = execMetadataOp(req);
    // HiveServer2 GetFunctions() has 6 columns.
    assertEquals(6, resp.schema.columns.size());
    assertEquals(6, resp.rows.get(0).colVals.size());
    Set<String> fns = Sets.newHashSet();
    for (TResultRow row : resp.rows) {
        String fn = row.colVals.get(2).string_val.toLowerCase();
        fns.add(fn);
    }
    assertEquals(3, fns.size());
    List<String> expectedResult = Lists.newArrayList();
    expectedResult.add("subdate");
    expectedResult.add("substr");
    expectedResult.add("substring");
    for (String fn : fns) {
        assertTrue(fn + " not found", expectedResult.remove(fn));
    }
}

@Test
public void testMetaDataGetTables() throws SQLException {
    // map from tablename search pattern to actual table name.
    Map<String, String> tests = new HashMap<String, String>();
    tests.put("alltypes", "alltypes");
    tests.put("%all_ypes", "alltypes");
    String[][] tblTypes = { null, { "TABLE" } };
    for (String tblNamePattern : tests.keySet()) {
        for (String[] tblType : tblTypes) {
            ResultSet rs = con_.getMetaData().getTables("", "functional", tblNamePattern, tblType);
            assertTrue(rs.next());
            // TABLE_NAME is the 3rd column.
            String resultTableName = rs.getString("TABLE_NAME");
            assertEquals(rs.getString(3), resultTableName);
            assertEquals("Table mismatch", tests.get(tblNamePattern), resultTableName);
            String tableType = rs.getString("TABLE_TYPE");
            assertEquals("table", tableType.toLowerCase());
            assertFalse(rs.next());
            rs.close();
        }
    }
    for (String[] tblType : tblTypes) {
        ResultSet rs = con_.getMetaData().getTables(null, null, null, tblType);
        // Should return at least one value.
        assertTrue(rs.next());
        rs.close();
        rs = con_.getMetaData().getTables(null, null, null, tblType);
        assertTrue(rs.next());
        rs.close();
    }
}

