@Test
public void testUserNoGroupsError() throws Exception {
    // Test fix for IMPALA-922: "Return helpful errors with Yarn group rules"
    createPoolService(ALLOCATION_FILE_GROUP_RULE, LLAMA_CONFIG_FILE);
    TResolveRequestPoolResult result = poolService_.resolveRequestPool(new TResolveRequestPoolParams("userA", "root.NOT_A_POOL"));
    Assert.assertEquals(false, result.isSetResolved_pool());
    Assert.assertEquals(false, result.isSetHas_access());
    Assert.assertEquals(TErrorCode.INTERNAL_ERROR, result.getStatus().getStatus_code());
    String expectedMessage = "Failed to resolve user 'userA' to a pool while " + "evaluating the 'primaryGroup' or 'secondaryGroup' queue placement rules because " + "no groups were found for the user. This is likely because the user does not " + "exist on the local operating system.";
    Assert.assertEquals(expectedMessage, Iterables.getOnlyElement(result.getStatus().getError_msgs()));
}

